GVL_Troubleshooting.CycleSemiAuto.Idx103_HeartbeatIhmOk            := Commun.HeartbeatIhmOk;
GVL_Troubleshooting.CycleSemiAuto.Idx104_DeadmanArmed              := JoystickDeadmanArmed;
GVL_Troubleshooting.CycleSemiAuto.Idx105_MancheDeflechi            := NOT JoystickAtNeutral;
GVL_Troubleshooting.CycleSemiAuto.Idx106_HomedM1M2                 := HomedM1 AND HomedM2;
GVL_Troubleshooting.CycleSemiAuto.Idx107_StartCycleRequest         := CycleStartRequest;
GVL_Troubleshooting.CycleSemiAuto.Idx108_AbortCycleRequest         := CycleAbortRequest;

GVL_Troubleshooting.CycleSemiAuto.Idx201_Ready                     := CycleReady;
GVL_Troubleshooting.CycleSemiAuto.Idx202_Busy                      := CycleAutoBusy;
GVL_Troubleshooting.CycleSemiAuto.Idx203_Done                      := CycleDone;
GVL_Troubleshooting.CycleSemiAuto.Idx204_Error                     := CycleError;
GVL_Troubleshooting.CycleSemiAuto.Idx205_ErrorId                   := CycleErrorId;
GVL_Troubleshooting.CycleSemiAuto.Idx206_Step                      := CycleStep;
GVL_Troubleshooting.CycleSemiAuto.Idx207_StepStr                   := CycleStepStr;
GVL_Troubleshooting.CycleSemiAuto.Idx208_StepAtError               := CycleStepAtError;

GVL_Troubleshooting.CycleSemiAuto.Idx301_TargetPosition            := CycleTargetPosition;
GVL_Troubleshooting.CycleSemiAuto.Idx302_TargetDepth_M             := CycleTargetDepth_M;
GVL_Troubleshooting.CycleSemiAuto.Idx303_KoboldBottomTouch         := CycleKoboldBottomTouch;
GVL_Troubleshooting.CycleSemiAuto.Idx304_SpeedMismatchActive       := CycleSpeedMismatchActive;
GVL_Troubleshooting.CycleSemiAuto.Idx305_LimitLegalReached         := CycleLimitLegalReached;
GVL_Troubleshooting.CycleSemiAuto.Idx306_WinchSyncError            := CycleWinchSyncError;
{endregion}

{region "§1 Gate et initialisation"}
IF NOT Enable OR NOT PowerContactorEngaged THEN
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    SpeedStep(Enable := FALSE, SpeedRefPct := 0.0, Table := SpeedStepTable, HystMargin := SpeedStepHystMargin);
    RequestedStep := SpeedStep.StepNumber;
    StepNumber := 0;
    BusinessStepDelay(IN := FALSE, PT := T#1s500ms);
    BusinessStepDelayElapsed := T#0ms;
    CommandedDirection := 0;
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelayAscent);
    DirectionChangeDelayElapsed := T#0ms;
    InTopSlowdownZone := FALSE;
    InBottomSlowdownZone := FALSE;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    StepNumber := 0;
    RequestedStep := 0;
    BusinessStepDelay(IN := FALSE, PT := T#1s500ms);
    BusinessStepDelayElapsed := T#0ms;
    RETURN;
END_IF;

{endregion}

{region "§2 Preparation commande et limites vitesse"}
Ready := TRUE;
CycleTimeCalc(DefaultValueS := 0.010);

ResetEdge(CLK := Reset);

DirectionChangePending := (Direction <> CommandedDirection) AND (CommandedDirection <> 0);

// Mou de câble / limite basse (DescendPermit=FALSE) et Fin de course haut (AscentPermit=FALSE)
// intégrés à une VRAIE décélération rapide (comme SafeStop) :
// - NOT DescendPermit est INHIBÉ si CommandedDirection = 1 (montée libre pour reprendre le mou)
// - NOT AscentPermit est INHIBÉ si CommandedDirection = -1 (descente libre pour dégager le câble)
EffectiveSafeStop := SafeStop 
                     OR (NOT DescendPermit AND (CommandedDirection <> 1))
                     OR (NOT AscentPermit AND (CommandedDirection <> -1));

RampTargetPct := 0.0;
IF NOT EffectiveSafeStop AND StartStop AND NOT DirectionChangePending THEN
    RampTargetPct := ABS(SpeedRefPct);
END_IF;

// RALENTISSEMENT AUTOMATIQUE SUR BORDURES (si référencé et non suspect) — permet d'approcher
// les fins de course / limites en vitesse lente de façon progressive.
// Plafond palier direct (ActiveMaxStep := 1, ci-dessous, même mécanisme que
// CfgMaxStepDescente/MaxStepAscent) — un treuil ne connaît que 5 paliers de contacteurs, pas une
// vitesse continue ; palier 1 = tous contacteurs de vitesse relâchés = vitesse minimale, sans
// dépendre d'un % qui doit rester sous le 1er seuil de la table pour produire le même effet.
InTopSlowdownZone := Homed AND NOT HomingSuspect
                      AND ((CommandedDirection = 1) OR (Direction = 1))
                      AND (CablePosM >= (TopLimitM - CfgSlowdownDistanceM));
InBottomSlowdownZone := Homed AND NOT HomingSuspect
                         AND ((CommandedDirection = -1) OR (Direction = -1))
                         AND (CablePosM <= (BottomLimitM + CfgSlowdownDistanceM));

// Délai asymétrique selon le sens ENTRANT (Direction) — descente sans effort
// (câble mou/gravité favorable) réengage plus vite que montée (charge en traction). La tempo
// palier se DÉDUIT de cet interlock (+100ms) : jamais besoin de resynchroniser deux réglages.
IF Direction = -1 THEN
    EffectiveDirectionInterlockDelay := DirectionInterlockDelayDescent;
ELSE
    EffectiveDirectionInterlockDelay := DirectionInterlockDelayAscent;
END_IF;
EffectiveStepDelay := EffectiveDirectionInterlockDelay + T#100ms;

IF Direction <> CommandedDirection THEN
    // Démarrage depuis le neutre/arrêt (CommandedDirection = 0) pris en compte IMMÉDIATE (0ms),
    // pas de tempo interlock. L'interlock DirectionChangeDelay (400ms descente / 900ms montée) ne
    // s'applique QU'EN CAS d'inversion active de sens en mouvement (ex: de -1 vers +1 direct).
    IF CommandedDirection = 0 THEN
        CommandedDirection := Direction;
        DirectionChangeDelay(IN := FALSE, PT := EffectiveDirectionInterlockDelay);
    ELSIF StepNumber = 0 THEN
        DirectionChangeDelay(IN := TRUE, PT := EffectiveDirectionInterlockDelay);
        IF DirectionChangeDelay.Q THEN
            CommandedDirection := Direction;
            DirectionChangeDelay(IN := FALSE, PT := EffectiveDirectionInterlockDelay);
        END_IF;
    ELSE
        DirectionChangeDelay(IN := FALSE, PT := EffectiveDirectionInterlockDelay);
    END_IF;
ELSE
    DirectionChangeDelay(IN := FALSE, PT := EffectiveDirectionInterlockDelay);
END_IF;
DirectionChangeDelayElapsed := DirectionChangeDelay.ET; // Diagnostic, miroir pur

// Plafond dynamique de palier (CfgMaxStepDescente en descente, Palier 1 si non référencé ou douteux,
// Palier 1 en approche homing, MaxStepAscent en montée normale)
IF NOT Homed OR HomingSuspect THEN
    // Bypass.Global = TRUE → pas de limitation, on applique la règle normale
    IF BypassGlobal THEN
        ActiveMaxStep := SEL(CommandedDirection = -1, MaxStepAscent, CfgMaxStepDescente);
    ELSE
        ActiveMaxStep := 1;
    END_IF;
ELSIF CommandedDirection = -1 THEN
    ActiveMaxStep := CfgMaxStepDescente;
ELSIF (CommandedDirection = 1) AND HomingApproachActive THEN
    ActiveMaxStep := 1;
ELSIF CommandedDirection = 1 THEN
    ActiveMaxStep := MaxStepAscent;
ELSE
    ActiveMaxStep := 5;
END_IF;

// Ralentissement sur bordure (voir plus haut) — plafond palier direct (CfgSlowdownMaxStep,
// défaut 1 = vitesse mini, réglable IHM), appliqué APRÈS le calcul normal ci-dessus via MIN
// (ne peut qu'abaisser, jamais relever le plafond déjà décidé par ailleurs — ex.
// CfgMaxStepDescente déjà plus restrictif).
IF InTopSlowdownZone OR InBottomSlowdownZone THEN
    ActiveMaxStep := MIN(ActiveMaxStep, CfgSlowdownMaxStep);
END_IF;

{endregion}

{region "§3 Selection et temporisation paliers"}
SpeedStep(Enable := (RampTargetPct > 0.1), SpeedRefPct := RampTargetPct,
          Table := SpeedStepTable, HystMargin := SpeedStepHystMargin,
          MaxStepNumber := ActiveMaxStep,
          MeasuredSpeedBand := MeasuredSpeedBand,
          SpeedGuardEnable := SpeedGuardEnable,
          SpeedGuardReady := SpeedGuardReady);
// 🪜 Tempo métier nominale : le décollage initial de StepNumber=0 vers 1 est IMMÉDIAT (0ms).
// Toute hausse ultérieure (1->2->3) exige EffectiveStepDelay (interlock + 100ms) et progresse par pas adjacents.
// Toute baisse reste immédiate pour ne jamais retarder un arrêt/safety.
RequestedStep := SpeedStep.StepNumber;
IF RequestedStep > StepNumber THEN
    IF StepNumber = 0 THEN
        StepNumber := 1;
        BusinessStepDelay(IN := FALSE, PT := EffectiveStepDelay);
        BusinessStepDelayElapsed := T#0ms;
    ELSE
        BusinessStepDelay(IN := TRUE, PT := EffectiveStepDelay);
        BusinessStepDelayElapsed := BusinessStepDelay.ET;
        IF BusinessStepDelay.Q THEN
            StepNumber := StepNumber + 1;
            BusinessStepDelay(IN := FALSE, PT := EffectiveStepDelay);
        END_IF;
    END_IF;
ELSE
    BusinessStepDelay(IN := FALSE, PT := EffectiveStepDelay);
    BusinessStepDelayElapsed := BusinessStepDelay.ET;
    StepNumber := RequestedStep;
END_IF;
SpeedGuardLimited := SpeedStep.SpeedGuardLimited;

{endregion}

{region "§4 Commandes contacteurs et sens"}
// Les sorties métier suivent le palier temporisé. FB_Winch/SpeedStepTable reste
// propriétaire unique des combinaisons, y compris les mappings M2 Benne dynamiques.
// FB_WinchOutputInterlock_LD ne fait qu'autoriser ou masquer ces quatre demandes.
CASE StepNumber OF
    1:
        Contactor1 := SpeedStepTable.P1R1; Contactor2 := SpeedStepTable.P1R2;
        Contactor3 := SpeedStepTable.P1R3; Contactor4 := SpeedStepTable.P1R4;
    2:
        Contactor1 := SpeedStepTable.P2R1; Contactor2 := SpeedStepTable.P2R2;
        Contactor3 := SpeedStepTable.P2R3; Contactor4 := SpeedStepTable.P2R4;
    3:
        Contactor1 := SpeedStepTable.P3R1; Contactor2 := SpeedStepTable.P3R2;
        Contactor3 := SpeedStepTable.P3R3; Contactor4 := SpeedStepTable.P3R4;
    4:
        Contactor1 := SpeedStepTable.P4R1; Contactor2 := SpeedStepTable.P4R2;
        Contactor3 := SpeedStepTable.P4R3; Contactor4 := SpeedStepTable.P4R4;
    5:
        Contactor1 := SpeedStepTable.P5R1; Contactor2 := SpeedStepTable.P5R2;
        Contactor3 := SpeedStepTable.P5R3; Contactor4 := SpeedStepTable.P5R4;
ELSE
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_CASE;

// Coupure INSTANTANÉE de tous les contacteurs de vitesse dès que l'opérateur relâche le
// joystick (Direction=0) — ne pas attendre la fin de la rampe de décélération. Sinon,
// StepNumber suivrait la rampe (décélération progressive), gardant les contacteurs de vitesse
// engagés plusieurs secondes après l'ordre d'arrêt.
IF Direction = 0 THEN
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_IF;

// Le sens et la pré-magnétisation suivent la demande brute ; le palier métier
// temporisé reste seul transmis à l'interlock final pour autoriser la puissance.
// ET Direction=1/-1 (demande OPÉRATEUR brute, pas CommandedDirection qui reste au dernier sens
// jusqu'à la retombée de la rampe) — coupure instantanée du contacteur de sens dès le
// relâchement du joystick, même sécurité que ci-dessus.
// Plus de terme BrakeSafetyOk — le frein n'est plus une condition d'engagement des relais de
// sens, c'est l'inverse (voir FB_WinchOutputInterlock_LD §6 : BrakeCmd := RelayFwd OR RelayRev,
// calculé APRÈS ces relais).
RelayFwd := (Direction = 1) AND (CommandedDirection = 1) AND (RequestedStep > 0);
RelayRev := (Direction = -1) AND (CommandedDirection = -1) AND (RequestedStep > 0);

IF NOT DescendPermit THEN
    RelayRev := FALSE;
END_IF;

IF NOT AscentPermit THEN
    RelayFwd := FALSE;
END_IF;

// Vérification UNIQUEMENT à l'arrêt commandé (plus de détail par sens — voir bandeau en-tête).
// AllContactorsCommandedOff = tout ce que FB_Winch commande est à FALSE.
AllContactorsCommandedOff := (NOT RelayFwd) AND (NOT RelayRev)
                             AND (NOT Contactor1) AND (NOT Contactor2) AND (NOT Contactor3) AND (NOT Contactor4);

ContactorsCheck.Command  := NOT AllContactorsCommandedOff;   // TRUE = au moins un contacteur commandé
ContactorsCheck.Feedback := NOT FwdRevSpeedFeedbackOff;      // TRUE = au moins un contacteur pas retombé
TonContactorsDropped(IN := AllContactorsCommandedOff AND NOT FwdRevSpeedFeedbackOff, PT := ContactorFeedbackTimeout);
IF TonContactorsDropped.Q THEN
    ContactorsCheck.StuckClosed := TRUE;
ELSIF ResetEdge.Q THEN
    ContactorsCheck.StuckClosed := FALSE;
END_IF;
ContactorsCheck.StuckOpen := FALSE; // Non applicable avec ce retour (pas de confirmation par sens, voir bandeau)

{endregion}

{region "§5 Diagnostic contacteurs et configuration"}
// 🌐 BYPASS GLOBAL : force ErrorId = 0 et saute toute la logique d'erreur
IF BypassGlobal THEN
    ErrorId := 16#0000;
END_IF;

IF NOT BypassGlobal THEN
// bit0 ErrorId libre — le frein n'est plus surveillé ici, sa cohérence commande/retour vit
// désormais dans FB_WinchOutputInterlock_LD (BrakeFeedback).

// 🧪 Simulation (GVL_Simulation.SensorMxContactorFeedbackIsReal, passé par l'appelant via
// BypassContactorCheck) — sans contacteurs réels câblés/cohérents en essai, StuckClosed
// se déclenche à tort et bloque RelayFwd/RelayRev (voir Error plus bas).
// bit2 (ex-RevContactorCheck) libre/inutilisé, fusionné dans bit1.
IF NOT BypassContactorCheck THEN
    IF ContactorsCheck.StuckClosed THEN
        ErrorId := ErrorId OR 16#0002;
    ELSIF ResetEdge.Q THEN
        ErrorId := ErrorId AND 16#FFFD;
    END_IF;
ELSE
    ErrorId := ErrorId AND 16#FFFD;   // Bypass actif : efface/maintient à 0 le bit1
END_IF;

// 🪜 WINCH-CORE-01 : remonte le défaut de configuration interne de FB_SpeedStep.
// Le bit reste mémorisé après correction de la table ; cause disparue + nouveau front Reset
// sont obligatoires avant de rendre le treuil disponible, conformément à Partie 3 §5.
IF SpeedStep.ConfigError THEN
    ErrorId := ErrorId OR 16#0004;    // bit2 = table/plafond/hystérésis invalide
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFB;
END_IF;

END_IF; // fin IF NOT BypassGlobal

{endregion}

{region "§6 Etats et repli defaut"}
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

IF (NOT StartStop OR EffectiveSafeStop OR DirectionChangePending) AND StepNumber > 0 THEN
    State := E_State.STOPPING;
ELSIF StepNumber > 0 THEN
    State := E_State.BUSY;
ELSE
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY) OR (State = E_State.STOPPING);
Done := FALSE;

IF Error THEN
    RelayFwd := FALSE;
    RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_IF;

{endregion}

{region "§1 Gate"}
// 🛑 1. GATE — aucune estimation lorsque le bloc est désactivé ou l'AU absent.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE;
    Busy := FALSE;
    Done := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    State := E_State.DISABLED;
    SpeedBand := 0;
    EstimatedLoadPct := 0.0;
    Configured := FALSE;
    Ascending := FALSE;
    HasPreviousBand := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
Busy := FALSE;
Done := FALSE;
State := E_State.READY;
ResetEdge(CLK := Reset);
Configured := LoadTable.IsConfigured;
// 📈 WINCH-CORE-01 : l'estimation de charge n'a de sens qu'en montée.
// La bande de vitesse reste calculée pour le diagnostic et le garde-fou de palier,
// mais EstimatedLoadPct est forcée à zéro à l'arrêt et en descente.
Ascending := (MeasuredSpeedSignedMps > 0.0);
{endregion}

{region "§2 Classement vitesse"}
// 📏 2. CLASSEMENT DE LA VITESSE — hystérésis autour des 4 frontières.
IF (MeasuredSpeedMps < 0.0) OR (SpeedConfig.MaxMeasuredSpeedMps <= 0.0) THEN
    ErrorId := ErrorId OR 16#0001;
    SpeedBand := 0;
ELSIF NOT HasPreviousBand THEN
    IF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[1] THEN
        PreviousSpeedBand := 1;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[2] THEN
        PreviousSpeedBand := 2;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[3] THEN
        PreviousSpeedBand := 3;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[4] THEN
        PreviousSpeedBand := 4;
    ELSE
        PreviousSpeedBand := 5;
    END_IF;
    HasPreviousBand := TRUE;
    SpeedBand := PreviousSpeedBand;
ELSE
    // 🔒 Valider l'état mémorisé avant toute indexation dynamique.
    IF PreviousSpeedBand < 1 OR PreviousSpeedBand > 5 THEN
        PreviousSpeedBand := 1;
        ErrorId := ErrorId OR 16#0001;
    END_IF;

    // CODESYS ne garantit pas le court-circuit des expressions AND :
    // chaque borne est donc testée dans une branche séparée avant accès.
    IF PreviousSpeedBand < 5 THEN
        IF MeasuredSpeedMps > (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand]
                               + SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand + 1;
        END_IF;
    END_IF;
    IF PreviousSpeedBand > 1 THEN
        IF MeasuredSpeedMps < (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand - 1]
                               - SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand - 1;
        END_IF;
    END_IF;
    SpeedBand := PreviousSpeedBand;
END_IF;
{endregion}

{region "§3 Lecture table"}
// 📊 3. LECTURE TABLE — bornes séparées avant l'accès au tableau 5x5.
EstimatedLoadPct := 0.0;
IF Configured THEN
    IF Ascending THEN
        IF ActiveSpeedStep >= 1 THEN
            IF ActiveSpeedStep <= 5 THEN
                IF SpeedBand >= 1 THEN
                    IF SpeedBand <= 5 THEN
                        SelectedLoadPct := LoadTable.LoadPctByStepAndSpeedBand[ActiveSpeedStep][SpeedBand];
                        IF (SelectedLoadPct < 0.0) OR (SelectedLoadPct > 100.0) THEN
                            ErrorId := ErrorId OR 16#0001;
                        ELSE
                            EstimatedLoadPct := SelectedLoadPct;
                        END_IF;
                    END_IF;
                END_IF;
            END_IF;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§4 Sorties et acquittement"}
// 📤 4. SORTIES D'ÉTAT ET ACQUITTEMENT.
IF ResetEdge.Q AND (ErrorId <> 16#0000) AND (MeasuredSpeedMps >= 0.0) THEN
    ErrorId := 16#0000;
END_IF;
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;
{endregion}

// ── 1. FRONT RESET AVANT GATE ───────────────────────────────────────────
// Le front est échantillonné même pendant Enable/AU faux : un Reset maintenu
// pendant une gate ne devient jamais un faux acquittement au retour.
ResetEdge(CLK := Reset);

// ── 2. GATE : neutralisation sûre ───────────────────────────────────────
// ErrorId, RestartInhibit et ResetRequired ne sont jamais effacés par une perte
// Enable/AU : celle-ci coupe uniquement les sorties. Le retour exige toujours un
// acquittement conscient puis une nouvelle demande opérateur.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    BrakeTimeout(IN := FALSE, PT := T#500ms);
    StepDelay(IN := FALSE, PT := T#1s250ms);
    RestartDelay(IN := FALSE, PT := T#1000ms);
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    BrakeCmd := FALSE; AuthorizedStep := 0;
    BrakeTimeoutElapsed := T#0ms; RestartDelayElapsed := T#0ms; StepDelayElapsed := T#0ms;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    Error := (ErrorId <> 16#0000);
    State := E_WinchFinalInterlockState.DISABLED;
    RestartRequired := TRUE;
    RETURN;
END_IF;

RequestedStepClamped := LIMIT(0, RequestedStep, 5);
// SafeStop reste une rampe rapide du FB_Winch (Enable maintenu, Partie 3 §1bis).
// La demande métier reste donc autorisée ici pendant la décélération ; l'interlock
// ne coupe qu'après sa retombée effective à zéro, sauf gate dur ou défaut final.
MotorRequest := (RequestedStepClamped > 0) AND (RequestedRelayFwd XOR RequestedRelayRev);

// ── 2bis. Arbitrage Error/ErrorId AVANT §3/§5 ────────────────────────────
// ErrorId bit0 (défaut frein) est mis à jour en FIN de scan (§6bis, après BrakeCmd) —
// la valeur lue ici est donc celle de la fin du scan PRÉCÉDENT (retard d'un scan sur une
// nouvelle occurrence, ~10ms, négligeable face au budget 500ms du watchdog). Voir bandeau.
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// ── 3. Réarmement anti-redémarrage automatique ──────────────────────────
// Après timeout : cause disparue + front Reset, puis demande moteur à zéro,
// puis nouvelle demande distincte. La retombée + T#1000ms sera ensuite refaite.
IF RestartInhibit AND NOT Error AND NOT ResetRequired AND NOT ResetEdge.Q THEN
    IF NOT MotorRequest THEN
        NeutralRequestSeen := TRUE;
        RestartRequired := TRUE;
    ELSIF NeutralRequestSeen AND MotorRequest THEN
        RestartInhibit := FALSE;
        NeutralRequestSeen := FALSE;
        RestartRequired := TRUE;
        Reason := E_WinchFinalInterlockReason.NONE;
    END_IF;
END_IF;

// ── 4. Mémorisation de l'arrêt : temporisation d'anti-redémarrage chaud ──────────
// La temporisation RestartDelay (1500ms) s'arme à l'arrêt du mouvement (NOT MotorRequest) et
// s'écoule pendant la pause à l'arrêt (au lieu de repartir de zéro à chaque nouvel appui) —
// permet un redémarrage instantané si la pause dépasse 1.5s. Le décompte ne démarre/continue que
// si le moteur n'est plus demandé ET que le frein est physiquement confirmé fermé
// (NOT BrakeFeedback = bobine retombée, mâchoires serrées). Garde le comportement "purge pendant
// la pause" (RestartRequired ne s'arme qu'à NOT MotorRequest, indépendant de la tempo).
IF NOT MotorRequest THEN
    RestartRequired := TRUE;
END_IF;
RestartDelay(IN := RestartRequired AND NOT MotorRequest AND NOT BrakeFeedback AND NOT RestartInhibit, PT := T#1500ms);
RestartDelayElapsed := RestartDelay.ET;
IF RestartDelay.Q THEN
    RestartRequired := FALSE;
END_IF;

// ── 5. Autorisation moteur ────────────────────────────────────────────────
RelayFwd := FALSE; RelayRev := FALSE;
Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
Busy := FALSE; Done := FALSE; Ready := NOT Error;

IF Error THEN
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.FAULT;
ELSIF RestartInhibit THEN
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    Reason := E_WinchFinalInterlockReason.RESTART_INHIBITED;
    State := E_WinchFinalInterlockState.FAULT;
ELSIF NOT MotorRequest THEN
    // Toute annulation de demande annule la temporisation de hausse en cours.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.READY;
ELSIF RestartRequired THEN
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.WAIT_RESTART_DELAY;
    Busy := TRUE;
ELSE
    // ⚡ Progression de palier directe : la temporisation (tempo palier) est gérée
    // par le métier (FB_Winch). La barrière finale transmet directement la consigne
    // sans micro-coupure des contacteurs.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := RequestedStepClamped;

    IF (AuthorizedStep > 0) OR (RequestedStepClamped > 0) THEN
        RelayFwd := RequestedRelayFwd;
        RelayRev := RequestedRelayRev;
        Contactor1 := RequestedContactor1;
        Contactor2 := RequestedContactor2;
        Contactor3 := RequestedContactor3;
        Contactor4 := RequestedContactor4;
    END_IF;

    IF NOT BrakeFeedback THEN
        State := E_WinchFinalInterlockState.WAIT_BRAKE_COMMAND_CONFIRMATION;
        Busy := TRUE;
    ELSE
        State := E_WinchFinalInterlockState.READY;
    END_IF;
END_IF;

// ── 6. Commande frein — couplage direct ────────────────────────────────
// BrakeCmd suit STRUCTURELLEMENT RelayFwd/RelayRev, calculé APRÈS leur
// finalisation ci-dessus (§5) : il hérite donc automatiquement de toutes leurs
// conditions de sécurité (Error, RestartInhibit, RestartRequired, MotorRequest)
// sans avoir à les répéter. Aucun risque d'écart frein/mouvement possible : le
// frein ne PEUT pas être commandé ouvert sans qu'un des deux relais de sens le
// soit aussi, puisque c'est la même expression. PRG_06_Outputs_LD recalcule la
// MÊME expression indépendamment sur les DQ finaux (M1RelayFwd OR M1RelayRev)
// pour piloter physiquement la bobine — ce BrakeCmd ici sert de miroir/diagnostic
// (State, IHM) mais n'est plus câblé sur la sortie physique (voir PRG_06 §2).
BrakeCmd := RelayFwd OR RelayRev;

// ── 6bis. Watchdog frein : uniquement sur la commande RÉELLEMENT FINALE ────
// Watchdog armé sur BrakeCmd (fin §5/§6), JAMAIS sur RequestedRelayFwd/Rev (demande amont pas
// encore autorisée par le state-machine §5 — RestartRequired peut la retenir jusqu'à T#1000ms,
// largement > le seuil 500ms ci-dessous, ce qui déclencherait un faux défaut à chaque redémarrage
// normal).
BrakeTimeout(IN := BrakeCmd AND NOT BrakeFeedback AND NOT RestartInhibit, PT := T#500ms);
BrakeTimeoutElapsed := BrakeTimeout.ET;
IF BrakeTimeout.Q THEN
    BrakeTimeoutCause := TRUE;
ELSIF BrakeFeedback THEN
    BrakeTimeoutCause := FALSE;   // cause réellement disparue (retour desserrage confirmé)
END_IF;
BrakeTimeoutCauseEdge(CLK := BrakeTimeoutCause);
IF BrakeTimeoutCauseEdge.Q THEN
    BrakeTimeoutAck := FALSE;    // nouvelle occurrence -> ré-alarme, ack remis à zéro
    RestartInhibit := TRUE;
    ResetRequired := TRUE;
    NeutralRequestSeen := FALSE;
    RestartRequired := TRUE;
    Reason := E_WinchFinalInterlockReason.BRAKE_COMMAND_NOT_CONFIRMED;
END_IF;
IF ResetEdge.Q THEN
    BrakeTimeoutAck := TRUE;     // toujours effectif, sans condition externe
    ResetRequired := FALSE;
END_IF;
IF BrakeTimeoutCause OR NOT BrakeTimeoutAck THEN
    ErrorId := ErrorId OR 16#0001;
ELSE
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_WinchSync) ===

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    State := E_State.DISABLED;
    DeltaPosM := 0.0;
    SyncActive := FALSE;
    SyncWarn := FALSE;
    SyncDegradedStep1 := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

{endregion}

{region "§2 Initialisation et activation synchro"}
Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🌐 BYPASS GLOBAL : force ErrorId = 0 et ignore toute la surveillance synchro
IF BypassGlobal THEN
    ErrorId := 16#0000;
END_IF;

// 🎚️ 3. SyncActive SELON MODE (Partie9 §9)
CASE Mode OF
    E_Mode.MAINT_N1:
        SyncActive := TRUE;                  // Imposée, non désactivable (sécurité maintenue N1)
    E_Mode.MAINT_N2:
        SyncActive := SyncEnable;             // Polarité positive (TRUE = synchro active)
    ELSE
        SyncActive := TRUE;                  // MANUEL/SEMI_AUTO : pas de logique dédiée (FB_Cycle absent), actif par prudence
END_CASE;

{endregion}

{region "§3 Calcul ecart position"}
// 📏 4. ÉCART M1/M2 — calculé en continu si les 2 treuils sont homés (même si BypassGlobal est actif)
IF HomedM1 AND HomedM2 THEN
    SignedDeltaPosM := CablePosM1 - CablePosM2 + ActiveOffsetM;
    DeltaPosM := ABS(SignedDeltaPosM);
ELSE
    SignedDeltaPosM := 0.0;
    DeltaPosM := 0.0;
END_IF;

{endregion}

{region "§4 Surveillance synchronisme"}
// 🌐 BYPASS GLOBAL : si actif, on saute TOUTE la logique d'erreur/surveillance
IF NOT BypassGlobal THEN

// 🔍 5. DÉTECTION ÉCART HORS TOLÉRANCE — bit0
// Filtre temporel (même pattern que MismatchTimer bit1) — absorbe le transitoire mécanique
// normal d'arrêt (coast-down différentiel M1/M2), évite le blocage intempestif.
// Si écart > CfgSyncToleranceM -> alarme d'écart (SyncWarn / bit0) et dégradation en vitesse
// lente Palier 1 (SyncDegradedStep1). L'arrêt brutal SafeStop est réservé à l'écart critique
// Méca E (> CriticalSyncToleranceM).
DeviationActive := SyncActive AND HomedM1 AND HomedM2 AND (DeltaPosM > CfgSyncToleranceM);
DeviationTimer(IN := DeviationActive, PT := T#800ms);  // 🔧 théorique, à ajuster sur site — absorbe le transitoire mécanique normal d'arrêt (coast-down différentiel M1/M2)
IF DeviationTimer.Q THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q AND NOT DeviationActive THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🐢 T113 : Dégradation au Palier 1 dès que l'écart dépasse la tolérance (sans attendre le SafeStop)
SyncDegradedStep1 := SyncActive AND HomedM1 AND HomedM2 AND ((DeltaPosM > CfgSyncToleranceM) OR ((ErrorId AND 16#0001) <> 16#0000));

// 🔍 5bis. COHÉRENCE DES COMMANDES SÉCURITÉ — bit1
// Vérifie que les commandes envoyées aux deux treuils sont identiques (sens et contacteurs)
// Filtre de 500ms pour tolérer les transitions et rampes.
MismatchActive := SyncActive AND (
    (RelayFwdM1 <> RelayFwdM2) OR
    (RelayRevM1 <> RelayRevM2) OR
    (Contactor1_M1 <> Contactor1_M2) OR
    (Contactor2_M1 <> Contactor2_M2) OR
    (Contactor3_M1 <> Contactor3_M2) OR
    (Contactor4_M1 <> Contactor4_M2)
);

MismatchTimer(IN := MismatchActive, PT := T#500ms);

IF MismatchTimer.Q THEN
    ErrorId := ErrorId OR 16#0002;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFD;
END_IF; // fin du IF MismatchActive

ELSE
    SyncDegradedStep1 := FALSE;
END_IF; // fin IF NOT BypassGlobal

{endregion}

{region "§5 Etats et diagnostic"}
// 📤 6. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

SyncWarn := Error;   // ⚠️ IHM uniquement — voir en-tête, pas de SafeStop
Busy := FALSE;
Done := FALSE;

{endregion}

{region "§1 Reset et qualification"}
CycleTime(DefaultValueS := 0.010); ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN Data.DeltaStartDelay_Ms:=0; Data.DeltaBrakeReleaseTime_Ms:=0; Data.DeltaBrakeApplyTime_Ms:=0; Data.DeltaStopDistance_Mm:=0; Data.DeltaStopTime_Ms:=0; Data.MaxSyncDeviation_M:=0.0; END_IF;
Comparable := M1CommandActive AND M2CommandActive AND (M1Direction = M2Direction) AND (M1Direction <> 0);
CommandTon(IN := Comparable, PT := UDINT_TO_TIME(Config.MinimumCommandTime_Ms));
Qualified := CommandTon.Q AND (M1Speed_Mps >= Config.MinimumSpeed_Mps) AND (M2Speed_Mps >= Config.MinimumSpeed_Mps);
MotionTimer(IN := Comparable, PT := T#1h);
StopTimer(IN := Stopping, PT := T#1h);
IF NOT Comparable THEN StartCapturedM1:=FALSE; StartCapturedM2:=FALSE; ReleaseMsM1:=0; ReleaseMsM2:=0; ApplyMsM1:=0; ApplyMsM2:=0; END_IF;
IF Comparable AND (M1Speed_Mps >= Config.MinimumSpeed_Mps) AND NOT StartCapturedM1 THEN StartMsM1:=TIME_TO_UDINT(MotionTimer.ET); StartCapturedM1:=TRUE; END_IF;
IF Comparable AND (M2Speed_Mps >= Config.MinimumSpeed_Mps) AND NOT StartCapturedM2 THEN StartMsM2:=TIME_TO_UDINT(MotionTimer.ET); StartCapturedM2:=TRUE; END_IF;
{endregion}

{region "§2 Mesure symétrie"}
IF Qualified THEN
    IF M1BrakeCmd AND M1BrakeApplied THEN ReleaseMsM1 := ReleaseMsM1 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF M2BrakeCmd AND M2BrakeApplied THEN ReleaseMsM2 := ReleaseMsM2 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF NOT M1BrakeCmd AND NOT M1BrakeApplied THEN ApplyMsM1 := ApplyMsM1 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF NOT M2BrakeCmd AND NOT M2BrakeApplied THEN ApplyMsM2 := ApplyMsM2 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF SyncDeviation_M > Data.MaxSyncDeviation_M THEN Data.MaxSyncDeviation_M := SyncDeviation_M; END_IF;
END_IF;
IF PreviousQualified AND NOT Comparable THEN Stopping:=TRUE; StopCapturedM1:=FALSE; StopCapturedM2:=FALSE; StopStartM1_M:=M1Position_M; StopStartM2_M:=M2Position_M; END_IF;
IF Stopping THEN
    IF (M1Speed_Mps < Config.MinimumSpeed_Mps) AND NOT StopCapturedM1 THEN StopMsM1:=TIME_TO_UDINT(StopTimer.ET); StopCapturedM1:=TRUE; END_IF;
    IF (M2Speed_Mps < Config.MinimumSpeed_Mps) AND NOT StopCapturedM2 THEN StopMsM2:=TIME_TO_UDINT(StopTimer.ET); StopCapturedM2:=TRUE; END_IF;
    IF StopCapturedM1 AND StopCapturedM2 THEN
        Data.DeltaStartDelay_Ms := ABS(UDINT_TO_DINT(StartMsM1)-UDINT_TO_DINT(StartMsM2));
        Data.DeltaBrakeReleaseTime_Ms := ABS(UDINT_TO_DINT(ReleaseMsM1)-UDINT_TO_DINT(ReleaseMsM2));
        Data.DeltaBrakeApplyTime_Ms := ABS(UDINT_TO_DINT(ApplyMsM1)-UDINT_TO_DINT(ApplyMsM2));
        Data.DeltaStopDistance_Mm := REAL_TO_UDINT(ABS(ABS(M1Position_M-StopStartM1_M)-ABS(M2Position_M-StopStartM2_M))*1000.0);
        Data.DeltaStopTime_Ms := ABS(UDINT_TO_DINT(StopMsM1)-UDINT_TO_DINT(StopMsM2)); Stopping:=FALSE; SymmetryValid:=TRUE;
    END_IF;
END_IF;
{endregion}

{region "§3 Sortie"}
SymmetryOk := SymmetryValid AND (Data.DeltaStartDelay_Ms<=Config.DeltaStartDelay_Ms) AND (Data.DeltaBrakeReleaseTime_Ms<=Config.DeltaBrakeReleaseTime_Ms) AND (Data.DeltaBrakeApplyTime_Ms<=Config.DeltaBrakeApplyTime_Ms) AND (Data.DeltaStopDistance_Mm<=Config.DeltaStopDistance_Mm) AND (Data.DeltaStopTime_Ms<=Config.DeltaStopTime_Ms);
PreviousQualified := Qualified;
{endregion}

{region "§0 Session simulation & aiguillage"}
// === 🧪 §0 SIMULATION & SÉLECTION DE SOURCE ===
// 🎯 Producteur unique des aiguillages Réel/Simu par domaine (HwReal vs HwSim -> HwIn).
// ⚡ Fronts maître : initialisent/nettoient les stimuli banc sans état résiduel.

SimulationModeRise(CLK := GVL_Simulation.SimulationModeActive);
SimulationModeFall(CLK := GVL_Simulation.SimulationModeActive);

IF SimulationModeRise.Q THEN
    GVL_Simulation.SimWinchActive := TRUE;
    GVL_Simulation.SimTranslationActive := TRUE;
    GVL_Simulation.SimOperatorActive := TRUE;
    GVL_Simulation.SimSafetyActive := TRUE;
    // Plus d'auto-arm `SimJoystickRawButton := TRUE` — il masquait le vrai
    // homme-mort (DeadmanArmed restait armé en permanence → rien de testé en sim). Le bouton
    // suit désormais le stimulus directionnel (FB_SimBench : JoyBtnRaw := SimJoystickRawButton
    // OR DirectionCount>0), ce qui rejoue fidèlement l'armement au commandement, la grâce 3 s
    // et la retombée au neutre. SimJoystickRawButton reste un appui manuel (défaut FALSE).
END_IF;

IF SimulationModeFall.Q THEN
    GVL_Simulation.SimWinchActive := FALSE;
    GVL_Simulation.SimTranslationActive := FALSE;
    GVL_Simulation.SimOperatorActive := FALSE;
    GVL_Simulation.SimSafetyActive := FALSE;

    GVL_Simulation.SimM3SensorsWordOverrideActive := FALSE;
    GVL_Simulation.SimM3SensorsWord := 16#07;
    GVL_Simulation.SimJoystickLeft_Rev_TREMIE_Active := FALSE;
    GVL_Simulation.SimJoystickRight_Fwd_MAINT_Active := FALSE;
    GVL_Simulation.SimJoystickFwd_Up_Close_Active := FALSE;
    GVL_Simulation.SimJoystickRev_Down_Open_Active := FALSE;
    GVL_Simulation.SimJoystickRawX := 5000;
    GVL_Simulation.SimJoystickRawY := 5000;
    GVL_Simulation.SimJoystickRawButton := FALSE;
    GVL_Simulation.SimEncoderSpeedFactor := 1.0;
    GVL_Simulation.SimSyncDeviationInjectM1 := FALSE;
    GVL_Simulation.SimSyncDeviationInjectM2 := FALSE;
    GVL_Simulation.SimSyncDeviationOffset_M := 0.5;
    GVL_Simulation.SimKoboldContactValue := FALSE;
END_IF;

// 🔀 Aiguillages de source uniques par domaine
WinchInputSourceSimulated       := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive;
TranslationInputSourceSimulated := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimTranslationActive;
OperatorInputSourceSimulated    := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimOperatorActive;
MachineInputSourceSimulated     := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimSafetyActive;
SimulationBypassActive          := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive AND GVL_Simulation.SimulationBypassActive;
{endregion}

{region "§1 Acquisition brute — HwReal"}
// === 📥 §1 ACQUISITION BRUTE MATÉRIELLE (HwReal) ===

// Winch M1 / M2 et codeurs
HwReal.Winch.M1_ContactorsReleased_DI := M1_ContactorsReleased_DI;
HwReal.Winch.M1_ThermalOk_DI          := M1_ThermalOk_DI;
HwReal.Winch.M1_BrakeIsOpen_DI        := M1_BrakeIsOpen_DI;

HwReal.Winch.M2_ContactorsReleased_DI := M2_ContactorsReleased_DI;
HwReal.Winch.M2_ThermalOk_DI          := M2_ThermalOk_DI;
HwReal.Winch.M2_BrakeIsOpen_DI        := M2_BrakeIsOpen_DI;

HwReal.Winch.M1M2_TopPositionFree_DI  := M1M2_TopPositionFree_DI;
HwReal.Winch.M2_TensionedCable_DI     := M2_TensionedCable_DI;

HwReal.Winch.COD1_PosValue            := COD1_PosValue;
HwReal.Winch.COD1_Alarms              := COD1_Alarms;
HwReal.Winch.COD1_Warnings            := COD1_Warnings;
HwReal.Winch.COD1_DeviceState         := COD1_CODEUR.GetDeviceState();

HwReal.Winch.COD2_PosValue            := COD2_PosValue;
HwReal.Winch.COD2_Alarms              := COD2_Alarms;
HwReal.Winch.COD2_Warnings            := COD2_Warnings;
HwReal.Winch.COD2_DeviceState         := COD2_CODEUR.GetDeviceState();

// Translation M3 et variateur AC600
HwReal.Translation.M3_PosTremie_DI      := M3_PosTremie_DI;
HwReal.Translation.M3_PosPV_DI          := M3_PosPV_DI;
HwReal.Translation.M3_PosPVP2_DI        := M3_PosPVP2_DI;
HwReal.Translation.M3_PosP1_DI          := M3_PosP1_DI;
HwReal.Translation.M3_PosMaintenance_DI := M3_PosMaintenance_DI;
HwReal.Translation.M3_BrakeIsOpen_DI    := M3_BrakeIsOpen_DI;
HwReal.Translation.M3_ThermalOK_DI       := M3_ThermalOK_DI;
HwReal.Translation.M3_StatusWord        := M3_StatusWord;
HwReal.Translation.M3_ActualFrequencyHz := M3_ActualFrequencyHz;
HwReal.Translation.AC600_DeviceState    := AC600_ECAT_Drive.GetDeviceState();

// Opérateur / Joystick / bus CANopen
HwReal.Operator.JoyXRaw_ANA1      := JoyXRaw_ANA1;
HwReal.Operator.JoyYRaw_ANA2      := JoyYRaw_ANA2;
HwReal.Operator.JoyBtnRaw         := JoyBtnRaw;
HwReal.Operator.CanBusState       := CANbus.GetBusState();
HwReal.Operator.JOY1_DeviceState  := JOY1_JOYSTICK_MCB560_CO4201A.GetDeviceState();

// Sécurités / Communs Machine
HwReal.Machine.PowerContactorEngaged_DI   := PowerContactorEngaged_DI;
HwReal.Machine.EmergencyChainClosed_DI    := EmergencyChainClosed_DI;
HwReal.Machine.PhaseRotationOk_DI         := PhaseRotationOk_DI;
HwReal.Machine.M1_M2_M3_BrakeThermalOk_DI  := M1_M2_M3_BrakeThermalOk_DI;
HwReal.Machine.M1_M2_KoboldBottomTouch_DI  := M1_M2_KoboldBottomTouch_DI;
HwReal.Machine.HydraulicThermalOk_DI       := HydraulicThermalOk_DI;
HwReal.Machine.ConveyorInfeedReady_DI      := ConveyorInfeedReady_DI;
HwReal.Machine.HopperFull_OR_GateRaised_DI := HopperFull_OR_GateRaised_DI; // Déclaré, pas encore consommé
{endregion}

{region "§1bis Diagnostic modules DI"}
// 🩺 Diagnostic carte des 3 modules DI portant les 22 TOR réelles (AF06 §3bis).
// GetDeviceState() = RUNNING => module opérationnel. Si la simulation globale/machine est active,
// les cartes physiques absentes sont simulées OK pour permettre le fonctionnement banc.
IF MachineInputSourceSimulated THEN
    LocalDigitalIoOk := TRUE;
    Vh0800EndOk      := TRUE;
    Vh0808EtpOk      := TRUE;
ELSE
    LocalDigitalIoOk := (Local_Digital_IO.GetDeviceState() = DEVICE_STATE.RUNNING);
    Vh0800EndOk      := (VH_0800END.GetDeviceState() = DEVICE_STATE.RUNNING);
    Vh0808EtpOk      := (VH_0808ETP.GetDeviceState() = DEVICE_STATE.RUNNING);
END_IF;
InputModuleFault := NOT (LocalDigitalIoOk AND Vh0800EndOk AND Vh0808EtpOk);
{endregion}

{region "§2 Simulation et aiguillage — HwIn"}
// === 🎭 §2 SIMULATION & AIGUILLAGE (HwIn) ===

instSimBench(
    Enable                   := GVL_Simulation.SimulationModeActive,
    M1_RelayFwd              := GVL_Global.M1RelayFwd,
    M1_RelayRev              := GVL_Global.M1RelayRev,
    M1_SpeedContactor_1      := GVL_Global.M1SpeedContactor1,
    M1_SpeedContactor_2      := GVL_Global.M1SpeedContactor2,
    M1_SpeedContactor_3      := GVL_Global.M1SpeedContactor3,
    M1_SpeedContactor_4      := GVL_Global.M1SpeedContactor4,
    M1_SpeedRefPct           := PRG_04_Treuils_Benne.M1LogicRequestSpeedRef_Pct,
    M1_PresetTriggerCmd      := instEncoderAbsM1.PresetTriggerCmd,
    M1_PresetValueOut        := instEncoderAbsM1.PresetValueOut,
    M1_BrakeCmd              := GVL_Global.M1BrakeCmd,
    M2_RelayFwd              := GVL_Global.M2RelayFwd,
    M2_RelayRev              := GVL_Global.M2RelayRev,
    M2_SpeedContactor_1      := GVL_Global.M2SpeedContactor1,
    M2_SpeedContactor_2      := GVL_Global.M2SpeedContactor2,
    M2_SpeedContactor_3      := GVL_Global.M2SpeedContactor3,
    M2_SpeedContactor_4      := GVL_Global.M2SpeedContactor4,
    M2_SpeedRefPct           := PRG_04_Treuils_Benne.M2LogicRequestSpeedRef_Pct,
    M2_PresetTriggerCmd      := instEncoderAbsM2.PresetTriggerCmd,
    M2_PresetValueOut        := instEncoderAbsM2.PresetValueOut,
    M2_BrakeCmd              := GVL_Global.M2BrakeCmd,
    M3_Direction             := PRG_05_Translation.M3_Direction_Active,
    M3_SpeedRefPct           := PRG_05_Translation.M3_SpeedRef_Active,
    M3_BrakeCmd              := GVL_Global.TranslationBrakeCmd,
    PowerKeepAlive_A         := PRG_06_Outputs_LD.PowerKeepAliveACmd,
    PowerKeepAlive_B         := PRG_06_Outputs_LD.PowerKeepAliveBCmd,
    // 🧪 Simulation uniquement : l'état étape 5 sécurise le transfert même si la sortie
    // inter-POU ArmPulse est observée avec un cycle de retard dans la tâche.
    EmergencyArming_RQ       := PRG_06_Outputs_LD.EmergencyArmingCmd
                                 OR (PRG_06_Outputs_LD.ArmingSeqStep = 5),
    SimEncoderSpeedFactor    := GVL_Simulation.SimEncoderSpeedFactor,
    SimSyncDeviationInjectM1 := GVL_Simulation.SimSyncDeviationInjectM1,
    SimSyncDeviationInjectM2 := GVL_Simulation.SimSyncDeviationInjectM2,
    SimSyncDeviationOffset_M := GVL_Simulation.SimSyncDeviationOffset_M,
    SimM3SensorsWordOverrideActive := GVL_Simulation.SimM3SensorsWordOverrideActive,
    SimM3SensorsWord               := GVL_Simulation.SimM3SensorsWord,
    SimJoystickLeft_Rev_TREMIE_Active  := GVL_Simulation.SimJoystickLeft_Rev_TREMIE_Active,
    SimJoystickRight_Fwd_MAINT_Active  := GVL_Simulation.SimJoystickRight_Fwd_MAINT_Active,
    SimJoystickFwd_Up_Close_Active     := GVL_Simulation.SimJoystickFwd_Up_Close_Active,
    SimJoystickRev_Down_Open_Active    := GVL_Simulation.SimJoystickRev_Down_Open_Active,
    SimJoystickRawX                    := GVL_Simulation.SimJoystickRawX,
    SimJoystickRawY                    := GVL_Simulation.SimJoystickRawY,
    SimJoystickRawButton               := GVL_Simulation.SimJoystickRawButton,
    SimKoboldContactValue    := GVL_Simulation.SimKoboldContactValue,
    BtnEmergencyStop         := GVL_IHM.Modes.Cmd.BtnEmergencyCutOff,
    HwReal                   := HwReal,
    RawPosM1                 := _SimEncoderRawPosM1,
    RawPosM2                 := _SimEncoderRawPosM2
);

// Exposition de l'image de simulation produite par le banc
HwSim.Winch       := instSimBench.Winch;
HwSim.Translation := instSimBench.Translation;
HwSim.Operator    := instSimBench.Operator;
HwSim.Machine     := instSimBench.Machine;

IF NOT WinchInputSourceInitialized THEN
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
    WinchInputSourceInitialized := TRUE;
    WinchInputSourceChanged := FALSE;
ELSE
    WinchInputSourceChanged := (WinchInputSourceSimulated <> PreviousWinchInputSourceSimulated);
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
END_IF;

// 🔧 SEL(G, IN0, IN1) : brique standard IEC 61131-3, retourne IN1 si G=TRUE, IN0 sinon
// (AF_Partie-03 §1 : composer l'existant avant réimplémentation) — remplace les 4 IF/ELSE
// compactés qui cassaient le générateur ST→LD (CODE_QUALITY_STANDARDS.md §11).
// Utilisation explicite de HwSim.* et des 4 variables de sélection par domaine.
HwIn.Winch       := SEL(WinchInputSourceSimulated, HwReal.Winch, HwSim.Winch);
HwIn.Translation := SEL(TranslationInputSourceSimulated, HwReal.Translation, HwSim.Translation);
HwIn.Operator    := SEL(OperatorInputSourceSimulated, HwReal.Operator, HwSim.Operator);
HwIn.Machine     := SEL(MachineInputSourceSimulated, HwReal.Machine, HwSim.Machine);
{endregion}


{region "§3 Traitement joystick"}
// === 🕹️ §3 TRAITEMENT JOYSTICK ===

instJoystick(
    Enable                    := TRUE,
    Reset                     := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged     := HwIn.Machine.PowerContactorEngaged_DI,
    Mode                      := PRG_03_Modes_Cycle.Auth.Mode,
    BenneBusy                 := PRG_04_Treuils_Benne.instBucket.Busy,
    PreserveArmingAfterBucket := PRG_04_Treuils_Benne.instExtractionSequence.Busy
                                 AND (PRG_04_Treuils_Benne.instExtractionSequence.ExtractionState = E_ExtractionSequenceState.CLOSING_BUCKET),
    BusCanOpenOP              := PRG_07_Supervision.instDiagCanOpen.DeviceCanOpenMaster,
    JoystickOP                := PRG_07_Supervision.instDiagCanOpen.DeviceJoystick,
    RawX                      := HwIn.Operator.JoyXRaw_ANA1,
    RawY                      := HwIn.Operator.JoyYRaw_ANA2,
    RawButton                 := HwIn.Operator.JoyBtnRaw,
    BtnCalibrate              := GVL_IHM.JOY1Joystick.Cmd.BtnCalibrate,
    InvertX                   := _JoystickInvertX,
    InvertY                   := _JoystickInvertY,
    DeadbandRaw               := _JoystickDeadbandRaw,
    FilterTime                := _JoystickFilterTime,
    NeutralHoldTime           := T#100MS,
    DeadmanArmHoldTime        := T#100MS,
    DeadmanArmGraceTime       := T#3S,
    NeutralXMem               := _JoystickNeutralX,
    NeutralYMem               := _JoystickNeutralY
);

// 📤 Publication des états et axes joystick
JoystickDeadmanArmed := instJoystick.DeadmanArmed;
JoystickYNeutral     := (instJoystick.DirectionY = 0);
JoystickDirectionX   := instJoystick.DirectionX;
JoystickSpeedPctX    := ABS(instJoystick.SpeedXPct);
JoystickXNeutral     := (instJoystick.DirectionX = 0);
{endregion}

{region "§4 Codeurs et homing — M1/M2"}
// === 🧲 §4 CODEURS & HOMING (M1 / M2) ===

// ── TREUIL M1 (Retenue) ──
instEncoderAbsM1(
    Enable                := TRUE,
    Reset                 := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged := HwIn.Machine.PowerContactorEngaged_DI,
    Mode                  := PRG_03_Modes_Cycle.Auth.Mode,
    RawPosIn              := HwIn.Winch.COD1_PosValue,
    AlarmsIn              := HwIn.Winch.COD1_Alarms,
    WarningsIn            := HwIn.Winch.COD1_Warnings,
    SlaveOperational      := PRG_07_Supervision.instDiagEthercat.DeviceEncoderM1.Operational,
    PresetRequest         := instHomingM1.PresetRequest,
    PresetValue           := instHomingM1.PresetValue
);

instHomingM1(
    Enable                 := TRUE,
    Reset                  := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged  := HwIn.Machine.PowerContactorEngaged_DI,
    Mode                   := PRG_03_Modes_Cycle.Auth.Mode,
    Home                   := GVL_IHM.M1TreuilRetenue.Cmd.BtnHome OR GVL_IHM.M1TreuilRetenue.Cmd.BtnHomingAtZero,
    UnitaryMode            := (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N2)
                              AND (PRG_03_Modes_Cycle.Auth.JoystickWinchSelectArbitrated <> 0),
    WinchSelected          := (PRG_03_Modes_Cycle.Auth.JoystickWinchSelectArbitrated = 1),
    CfgHomingTargetM       := _WinchM1CfgPersist.CfgHomingTarget_M,
    BtnConfirmCoherence    := GVL_IHM.M1TreuilRetenue.Cmd.BtnConfirmCoherence,
    TopPositionSensor      := HwIn.Winch.M1M2_TopPositionFree_DI,
    CfgTopSensorPosM       := SEL(GVL_IHM.M1TreuilRetenue.Cmd.BtnHomingAtZero, _WinchM1CfgPersist.CfgTopSensorPos_M, 0.0),
    FwdRevSpeedFeedbackOff := HwIn.Winch.M1_ContactorsReleased_DI,
    BrakeFeedback          := HwIn.Winch.M1_BrakeIsOpen_DI,
    RawPos                 := instEncoderAbsM1.RawPos,
    EncoderAvailable       := instEncoderAbsM1.EncoderAvailable,
    PresetAck              := instEncoderAbsM1.PresetAck,
    PresetNak              := instEncoderAbsM1.PresetNak,
    PointsPerRev           := ENCODER_POINTS_PER_REV,
    MultiTurnRevsMax       := ENCODER_MULTITURN_REVS_MAX,
    CableM_PerRev          := WINCH_CABLE_M_PER_REV,
    BypassGlobal           := GVL_IHM.M1TreuilRetenue.Bypass.Global,
    Calib                  := _CalibM1
);

instEncoderScaleM1(
    RawPos        := instEncoderAbsM1.RawPos,
    HomingRefRaw  := instHomingM1.HomingRefRaw,
    CableM_PerRev := WINCH_CABLE_M_PER_REV,
    PointsPerRev  := ENCODER_POINTS_PER_REV
);

instEncoderSafetyM1(
    Enable                := TRUE,
    Reset                 := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged := HwIn.Machine.PowerContactorEngaged_DI,
    Mode                  := PRG_03_Modes_Cycle.Auth.Mode,
    CablePosM             := instEncoderScaleM1.CablePosM,
    HomingSuspect         := instHomingM1.HomingSuspect,
    BypassGlobal          := GVL_IHM.M1TreuilRetenue.Bypass.Global
);
CablePosM1           := instEncoderSafetyM1.CablePosMSafe;
M1_EncoderIncoherent := instEncoderSafetyM1.EncoderIncoherent;

instEncoderSpeedMeasureM1(
    Enable        := TRUE,
    Reset         := PRG_07_Supervision.FaultMachineReset_IHM,
    Position_M    := instEncoderSafetyM1.CablePosMSafe,
    PositionValid := instEncoderAbsM1.EncoderAvailable AND NOT instEncoderSafetyM1.EncoderIncoherent
);
M1_Speed_Mps       := instEncoderSpeedMeasureM1.Speed_Mps;
M1_SignedSpeed_Mps := instEncoderSpeedMeasureM1.SignedSpeed_Mps;
M1_SpeedValid      := instEncoderSpeedMeasureM1.Valid;

// ── TREUIL M2 (Benne) ──
instEncoderAbsM2(
    Enable                := TRUE,
    Reset                 := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged := HwIn.Machine.PowerContactorEngaged_DI,
    Mode                  := PRG_03_Modes_Cycle.Auth.Mode,
    RawPosIn              := HwIn.Winch.COD2_PosValue,
    AlarmsIn              := HwIn.Winch.COD2_Alarms,
    WarningsIn            := HwIn.Winch.COD2_Warnings,
    SlaveOperational      := PRG_07_Supervision.instDiagEthercat.DeviceEncoderM2.Operational,
    PresetRequest         := instHomingM2.PresetRequest,
    PresetValue           := instHomingM2.PresetValue
);

// Synchronisation référencement M2 sur ouverture/fermeture benne
M2BucketRefOpenEdge(CLK := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmOpenPos);
M2BucketRefCloseEdge(CLK := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmClosePos);
M2BucketRefRequested := (M2BucketRefOpenEdge.Q OR M2BucketRefCloseEdge.Q)
    AND (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N1 OR PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N2)
    AND NOT PRG_04_Treuils_Benne.instWinchM1.Busy AND NOT PRG_04_Treuils_Benne.instWinchM2.Busy;
IF M2BucketRefRequested AND M2BucketRefOpenEdge.Q THEN
    M2BucketRefTargetM := CablePosM1;
ELSIF M2BucketRefRequested AND M2BucketRefCloseEdge.Q THEN
    M2BucketRefTargetM := CablePosM1 + _BucketCfgPersist.Config.OffsetCloseM;
END_IF;

instHomingM2(
    Enable                 := TRUE,
    Reset                  := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged  := HwIn.Machine.PowerContactorEngaged_DI,
    Mode                   := PRG_03_Modes_Cycle.Auth.Mode,
    Home                   := GVL_IHM.M2TreuilBenne.Cmd.BtnHome OR GVL_IHM.M2TreuilBenne.Cmd.BtnHomingAtZero OR M2BucketRefRequested,
    UseDynamicTarget       := M2BucketRefRequested,
    DynamicHomingTargetM   := M2BucketRefTargetM,
    UnitaryMode            := (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N2)
                              AND (PRG_03_Modes_Cycle.Auth.JoystickWinchSelectArbitrated <> 0),
    WinchSelected          := (PRG_03_Modes_Cycle.Auth.JoystickWinchSelectArbitrated = 2),
    CfgHomingTargetM       := _WinchM2CfgPersist.CfgHomingTarget_M,
    BtnConfirmCoherence    := GVL_IHM.M2TreuilBenne.Cmd.BtnConfirmCoherence,
    TopPositionSensor      := HwIn.Winch.M1M2_TopPositionFree_DI,
    CfgTopSensorPosM       := SEL(GVL_IHM.M2TreuilBenne.Cmd.BtnHomingAtZero, _WinchM2CfgPersist.CfgTopSensorPos_M, 0.0),
    FwdRevSpeedFeedbackOff := HwIn.Winch.M2_ContactorsReleased_DI,
    BrakeFeedback          := HwIn.Winch.M2_BrakeIsOpen_DI,
    RawPos                 := instEncoderAbsM2.RawPos,
    EncoderAvailable       := instEncoderAbsM2.EncoderAvailable,
    PresetAck              := instEncoderAbsM2.PresetAck,
    PresetNak              := instEncoderAbsM2.PresetNak,
    PointsPerRev           := ENCODER_POINTS_PER_REV,
    MultiTurnRevsMax       := ENCODER_MULTITURN_REVS_MAX,
    CableM_PerRev          := WINCH_CABLE_M_PER_REV,
    BypassGlobal           := GVL_IHM.M2TreuilBenne.Bypass.Global,
    Calib                  := _CalibM2
);

instEncoderScaleM2(
    RawPos        := instEncoderAbsM2.RawPos,
    HomingRefRaw  := instHomingM2.HomingRefRaw,
    CableM_PerRev := WINCH_CABLE_M_PER_REV,
    PointsPerRev  := ENCODER_POINTS_PER_REV
);

instEncoderSafetyM2(
    Enable                := TRUE,
    Reset                 := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged := HwIn.Machine.PowerContactorEngaged_DI,
    Mode                  := PRG_03_Modes_Cycle.Auth.Mode,
    CablePosM             := instEncoderScaleM2.CablePosM,
    HomingSuspect         := instHomingM2.HomingSuspect,
    BypassGlobal          := GVL_IHM.M2TreuilBenne.Bypass.Global
);
CablePosM2           := instEncoderSafetyM2.CablePosMSafe;
M2_EncoderIncoherent := instEncoderSafetyM2.EncoderIncoherent;

instEncoderSpeedMeasureM2(
    Enable        := TRUE,
    Reset         := PRG_07_Supervision.FaultMachineReset_IHM,
    Position_M    := instEncoderSafetyM2.CablePosMSafe,
    PositionValid := instEncoderAbsM2.EncoderAvailable AND NOT instEncoderSafetyM2.EncoderIncoherent
);
M2_Speed_Mps       := instEncoderSpeedMeasureM2.Speed_Mps;
M2_SignedSpeed_Mps := instEncoderSpeedMeasureM2.SignedSpeed_Mps;
M2_SpeedValid      := instEncoderSpeedMeasureM2.Valid;
{endregion}

{region "§5 Décodage position translation — M3"}
// === ↔️ §5 DÉCODAGE POSITION TRANSLATION (M3) ===

instPosDecoderM3(
    SensorTremie      := HwIn.Translation.M3_PosTremie_DI,
    SensorPV          := HwIn.Translation.M3_PosPV_DI,
    SensorP2          := HwIn.Translation.M3_PosPVP2_DI,
    SensorP1          := HwIn.Translation.M3_PosP1_DI,
    SensorMaintenance := HwIn.Translation.M3_PosMaintenance_DI
);

TranslationPosTremie      := instPosDecoderM3.TranslationPosTremie;
TranslationPosPV          := instPosDecoderM3.TranslationPosPV;
TranslationPosP2          := instPosDecoderM3.TranslationPosP2;
TranslationPosP1          := instPosDecoderM3.TranslationPosP1;
TranslationPosMaintenance := instPosDecoderM3.TranslationPosMaintenance;
TranslationAtTremie      := instPosDecoderM3.TranslationAtTremie;
TranslationAtPV          := instPosDecoderM3.TranslationAtPV;
TranslationAtP2          := instPosDecoderM3.TranslationAtP2;
TranslationAtP1          := instPosDecoderM3.TranslationAtP1;
TranslationAtMaintenance := instPosDecoderM3.TranslationAtMaintenance;
M3_LimitSwitchFwd       := instPosDecoderM3.LimitSwitchFwd;
M3_LimitSwitchRev       := instPosDecoderM3.LimitSwitchRev;
M3_SensorWordIncoherent := instPosDecoderM3.Incoherent;
{endregion}

{region "§6 Retours variateur — M3"}
// === 📊 §6 RETOURS VARIATEUR (M3) CONDITIONNÉS ===
M3_StatusWord_Filtered        := WORD_TO_UINT(HwIn.Translation.M3_StatusWord);
M3_ActualFrequencyHz_Filtered := HwIn.Translation.M3_ActualFrequencyHz;
{endregion}

// === 🔀 §1 ARBITRAGE DES MODES MACHINE ===
instModes( Enable := TRUE, Reset := GVL_IHM.Modes.Cmd.BtnModeReset, PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI, SelMode := GVL_IHM.Modes.Cmd.SelMode, SelSyncEnable := GVL_IHM.M1M2Sync.Cmd.SelSyncEnable, InhibitM1Request := GVL_IHM.M1TreuilRetenue.Cmd.BtnInhibit, InhibitM2Request := GVL_IHM.M2TreuilBenne.Cmd.BtnInhibit, SelHomingApproachEnable := GVL_IHM.Commun.Cfg.SelHomingApproachEnable, EncoderFaultPresent := (PRG_02_Acquisition.HwIn.Winch.COD1_DeviceState <> DEVICE_STATE.RUNNING) OR (PRG_02_Acquisition.HwIn.Winch.COD2_DeviceState <> DEVICE_STATE.RUNNING), JoystickWinchSelectRequest := GVL_IHM.Modes.Cmd.SelJoystickWinch, SelMaintenanceZoneAccess := GVL_IHM.TranslationM3.Cmd.TglMaintenanceZoneAccess );
// === 🔄 §2 SÉQUENCEUR DE CYCLE SEMI-AUTOMATIQUE === // 🕹️ CycleMotionPermit = manche défléchi (non centré) — D2 // ⚠️ Entrées sans source définie câblées en fail-safe documenté : // - SpeedMismatchThresholdMps := 0 / SpeedMismatchTimeout := T#0ms (contrôle désactivé) // - Benne_IsRoughlyClosed := Benne_IsClosed (fallback sûr : exige fermé) // - HomingRequest := bouton homing IHM (BtnHome M1 OU M2)
instCycleSemiAuto( Enable := (Auth.Mode = E_Mode.SEMI_AUTO), Reset := GVL_IHM.Cycle.Cmd.BtnReset, PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI, Mode := Auth.Mode, CycleMotionPermit := NOT PRG_02_Acquisition.instJoystick.AtNeutral, DeadmanArmed := PRG_02_Acquisition.JoystickDeadmanArmed, HeartbeatIhmOk := GVL_IHM.Commun.HeartbeatIhmOk, StartCycle := GVL_IHM.Cycle.Cmd.BtnStart, AbortCycle := GVL_IHM.Cycle.Cmd.BtnAbort, SelTarget := GVL_IHM.TranslationM3.Cmd.SelTarget, SetDepthM := GVL_IHM.Cycle.Cfg.SetDepth_M, SetOffsetM := GVL_IHM.Cycle.Cfg.SetOffset_M, KoboldContactFond := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI, LimitLegalReached := GVL_IHM.Commun.LimitLegalReached, LimitLegalDepthM := _CommunCfgPersist.LimitLegalDepthMinAllowed_M, WinchSyncError := PRG_04_Treuils_Benne.instWinchSync.Error, WinchSyncDeltaM := PRG_04_Treuils_Benne.instWinchSync.SignedDeltaPosM, M1_CablePosM := PRG_02_Acquisition.CablePosM1, M2_CablePosM := PRG_02_Acquisition.CablePosM2, M1_MeasuredSpeedMps := PRG_02_Acquisition.M1_Speed_Mps, M2_MeasuredSpeedMps := PRG_02_Acquisition.M2_Speed_Mps, SpeedMismatchThresholdMps := 1.5, // Seuil écart vitesse M1/M2 (revue : ~1-2 m/s, retenu 1.5) SpeedMismatchTimeout := T#500ms, // Tempo confirmation écart vitesse (revue) CableLimitM1AscentM := _WinchM1CfgPersist.CfgCableLimitAscent_M, Translation_At_P1 := PRG_05_Translation.M3_AtP1Stable, Translation_At_Tremie := PRG_05_Translation.M3_AtTremieStable, Translation_At_Maintenance := PRG_05_Translation.M3_AtMaintenanceStable, Translation_Busy := PRG_05_Translation.instTranslationM3.Busy, Translation_Done := PRG_05_Translation.instTranslationM3.Done, Benne_Busy := PRG_04_Treuils_Benne.instBucket.Busy, Benne_Done := PRG_04_Treuils_Benne.instBucket.Done, Benne_IsOpen := PRG_04_Treuils_Benne.BucketState.MechState.IsOpen, Benne_IsClosed := PRG_04_Treuils_Benne.BucketState.MechState.IsClosed, Benne_IsRoughlyClosed := PRG_04_Treuils_Benne.Benne_IsRoughlyClosed, // Tolérance matière 2m HomedM1 := PRG_02_Acquisition.instHomingM1.Homed, HomedM2 := PRG_02_Acquisition.instHomingM2.Homed, TopPositionSensor := PRG_02_Acquisition.HwIn.Winch.M1M2_TopPositionFree_DI, HomingRequest := GVL_IHM.M1TreuilRetenue.Cmd.BtnHome OR GVL_IHM.M2TreuilBenne.Cmd.BtnHome, SampleCount := _CycleSampleCount );
// === 📤 §3 PUBLICATION DU BUS AUTORISATIONS ===
Auth := instModes.Auth;

{region "§1 Intention maintenance et assistants"}
// === 🪨 §1 INTENTION MAINTENANCE & ASSISTANTS ===

IF GVL_IHM.Modes.Cmd.TglJoystickMaster THEN
    // : ancienne version
    // affectait HwIn.Operator.JoyYRaw_ANA2 (valeur analogique BRUTE 0..10000, meme signal que
    // RawY sur instJoystick) directement a CoupledUserRequestDirection, alors que
    // FB_Bucket/FB_DiveSearch/FB_ExtractionSequence testent MotionDirection = 1/-1 EXACTEMENT.
    // Consequence : en mode TglJoystickMaster, la benne/les sequenceurs assistes ne pouvaient
    // JAMAIS demarrer via le joystick (seul le mode Boutons IHM, qui affecte bien 1/-1,
    // fonctionnait). Corrige : direction deja mise a l'echelle (-1/0/+1) par instJoystick.
    CoupledUserRequestDirection := PRG_02_Acquisition.instJoystick.AxisCmdY.Direction;
    CoupledUserRequestActive := PRG_02_Acquisition.HwIn.Operator.JoyBtnRaw
                                     AND (PRG_03_Modes_Cycle.Auth.JoystickWinchSelectArbitrated = 0);

ELSE
    IF GVL_IHM.Commun.BtnWinchBothUp THEN
        CoupledUserRequestDirection := 1;
    ELSIF GVL_IHM.Commun.BtnWinchBothDown THEN
        CoupledUserRequestDirection := -1;
    ELSE
        CoupledUserRequestDirection := 0;
    END_IF;
    CoupledUserRequestActive := (CoupledUserRequestDirection <> 0);

END_IF;

// mode "vidage à la trémie" (verrouillage, demande client). Périmètre identique
// à instDiveSearch/instExtractionSequence : MAINT_N1/MAINT_N2 uniquement.
DumpAtTremieActive := GVL_IHM.DredgingAssist.Cmd.TglEnableDumpAtTremie;
DumpAtTremieAssistActive := DumpAtTremieActive
    AND (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N1 OR PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N2);
GVL_IHM.DredgingAssist.State.DumpAtTremieArmed        := DumpAtTremieActive;
GVL_IHM.DredgingAssist.State.DumpAtTremieAssistActive := DumpAtTremieAssistActive;
GVL_IHM.DredgingAssist.State.DumpAtTremieAtTremie     := PRG_05_Translation.M3_AtTremieStable;

// BUG CONFIRMÉ : "OR _BucketState.IsOpen" annulait le
// forçage à CHAQUE scan, alors que confirmer "fond touché" se fait précisément PENDANT que la
// benne est encore ouverte (avant que l'extraction ne la ferme) -- condition backwards, rendait
// tout forçage manuel de TglBucketAtBottomConfirmed impossible en pratique. Retiré.
IF NOT (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N1 OR PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N2)
   OR NOT PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI
   OR PRG_07_Supervision.FaultMachineReset_IHM
   OR (CoupledUserRequestActive AND (CoupledUserRequestDirection = -1)) THEN
    GVL_IHM.DredgingAssist.Cmd.TglBucketAtBottomConfirmed := FALSE;
    BypassKoboldBottomTouched := FALSE;
END_IF;
ManualBottomPositionConfirmed := GVL_IHM.DredgingAssist.Cmd.TglBucketAtBottomConfirmed;

// demande client : REMPLACÉ front montant par front
// DESCENDANT Kobold pendant une descente couplée = fond touché, directement (voir bandeau §1).
// Mêmes conditions de garde que la confirmation manuelle ci-dessus (MAINT_N1/N2, sous tension,
// pas de défaut, benne fermée -- réutilise le bloc de clear commun juste au-dessus).
BypassKoboldFallEdge(CLK := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI);
IF GVL_IHM.DredgingAssist.Cmd.TglBypassDiveSearchSequence
   AND CoupledUserRequestActive AND (CoupledUserRequestDirection = -1)
   AND BypassKoboldFallEdge.Q THEN
    BypassKoboldBottomTouched := TRUE;
END_IF;
GVL_IHM.DredgingAssist.State.BypassDiveActive          := GVL_IHM.DredgingAssist.Cmd.TglBypassDiveSearchSequence;
GVL_IHM.DredgingAssist.State.BypassKoboldBottomTouched := BypassKoboldBottomTouched;

instDiveSearch(
    Enable := (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N1 OR PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N2)
              AND GVL_IHM.DredgingAssist.Cmd.TglEnableDiveSearch,
    Reset := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode := PRG_03_Modes_Cycle.Auth.Mode,
    MotionRequestActive := CoupledUserRequestActive,
    MotionDirection := CoupledUserRequestDirection,
    BucketIsOpen := _BucketState.IsOpen,
    KoboldImmersed := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI,
    M1Position_M := PRG_02_Acquisition.CablePosM1,
    M2Position_M := PRG_02_Acquisition.CablePosM2,
    PositionsValid := PRG_02_Acquisition.instEncoderAbsM1.EncoderAvailable AND NOT PRG_02_Acquisition.M1_EncoderIncoherent
                       AND PRG_02_Acquisition.instEncoderAbsM2.EncoderAvailable AND NOT PRG_02_Acquisition.M2_EncoderIncoherent,
    DiveStartMin_M := GVL_IHM.DredgingAssist.Cfg.DiveStartMin_M,
    ImmersionUpper_M := GVL_IHM.DredgingAssist.Cfg.ImmersionUpper_M,
    ImmersionLower_M := GVL_IHM.DredgingAssist.Cfg.ImmersionLower_M,
    // (14) : même toggle que le bypass bottom-confirmation -- réglages seuils pas
    // encore calibrés, saute WAIT_PRECONDITIONS entièrement le temps des essais.
    BypassPreconditions := GVL_IHM.DredgingAssist.Cmd.TglBypassDiveSearchSequence
);

// publication IHM (était orpheline -- déclarée mais jamais écrite, voir
// GVL_IHM.DredgingAssist.State) — consommée ensuite par FB_TroubleshootingView (debug).
GVL_IHM.DredgingAssist.State.DiveReady            := instDiveSearch.Ready;
GVL_IHM.DredgingAssist.State.DiveBusy             := instDiveSearch.Busy;
GVL_IHM.DredgingAssist.State.DiveDone             := instDiveSearch.Done;
GVL_IHM.DredgingAssist.State.DiveError            := instDiveSearch.Error;
GVL_IHM.DredgingAssist.State.DiveErrorId          := instDiveSearch.ErrorId;
GVL_IHM.DredgingAssist.State.DiveState            := instDiveSearch.DiveState;
// : affichage IHM ne reflétait que la détection Kobold
// (instDiveSearch), pas la confirmation manuelle (TglBucketAtBottomConfirmed) ni le bypass --
// alors que BottomPositionConfirmed (consommée par instExtractionSequence ci-dessous) fait bien
// le OR des trois. L'opérateur voyait "non confirmé" à l'IHM alors que le séquenceur considérait
// le fond confirmé -- affichage seul en cause, la logique de commande était correcte.
BottomPositionConfirmed := instDiveSearch.BottomTouchConfirmed OR ManualBottomPositionConfirmed OR BypassKoboldBottomTouched;
GVL_IHM.DredgingAssist.State.BottomTouchConfirmed := BottomPositionConfirmed;

instExtractionSequence(
    Enable := (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N1 OR PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N2)
              AND GVL_IHM.DredgingAssist.Cmd.TglEnableExtractionSequence,
    Reset := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode := PRG_03_Modes_Cycle.Auth.Mode,
    MotionRequestActive := CoupledUserRequestActive,
    MotionDirection := CoupledUserRequestDirection,
    BottomPositionConfirmed := BottomPositionConfirmed,
    BucketIsClosed := _BucketState.IsClosed,
    BucketBusy := instBucket.Busy,
    BucketError := instBucket.Error,
    WinchSyncError := instWinchSync.Error,
    M1Position_M := PRG_02_Acquisition.CablePosM1,
    M2Position_M := PRG_02_Acquisition.CablePosM2,
    M1MeasuredSpeedValid := PRG_02_Acquisition.M1_SpeedValid,
    M2MeasuredSpeedValid := PRG_02_Acquisition.M2_SpeedValid,
    PositionsValid := PRG_02_Acquisition.instEncoderAbsM1.EncoderAvailable AND NOT PRG_02_Acquisition.M1_EncoderIncoherent
                       AND PRG_02_Acquisition.instEncoderAbsM2.EncoderAvailable AND NOT PRG_02_Acquisition.M2_EncoderIncoherent,
    ControlAscentDistance_M := GVL_IHM.DredgingAssist.Cfg.ExtractionControlDistance_M
);
IF instExtractionSequence.BottomConfirmationConsumed THEN
    GVL_IHM.DredgingAssist.Cmd.TglBucketAtBottomConfirmed := FALSE;
END_IF;

// Publication IHM (voir DiveSearch ci-dessus).
GVL_IHM.DredgingAssist.State.ExtractionReady   := instExtractionSequence.Ready;
GVL_IHM.DredgingAssist.State.ExtractionBusy    := instExtractionSequence.Busy;
GVL_IHM.DredgingAssist.State.ExtractionDone    := instExtractionSequence.Done;
GVL_IHM.DredgingAssist.State.ExtractionError   := instExtractionSequence.Error;
GVL_IHM.DredgingAssist.State.ExtractionErrorId := instExtractionSequence.ErrorId;
GVL_IHM.DredgingAssist.State.ExtractionState   := instExtractionSequence.ExtractionState;

// une seule consigne opérateur conduite à la fois (doc §OperatorActionId) —
// aucun PRG_09 n'existe (jamais câblé), arbitrage fait ici : DiveSearch prioritaire si Busy,
// sinon ExtractionSequence si Busy, sinon la dernière connue reste affichée à titre informatif.
IF instDiveSearch.Busy THEN
    GVL_IHM.DredgingAssist.State.OperatorActionId := instDiveSearch.OperatorActionId;
    GVL_IHM.DredgingAssist.State.OperatorAction   := instDiveSearch.OperatorAction;
ELSIF instExtractionSequence.Busy THEN
    GVL_IHM.DredgingAssist.State.OperatorActionId := instExtractionSequence.OperatorActionId;
    GVL_IHM.DredgingAssist.State.OperatorAction   := instExtractionSequence.OperatorAction;
ELSE
    GVL_IHM.DredgingAssist.State.OperatorActionId := 0;
    GVL_IHM.DredgingAssist.State.OperatorAction   := '';
END_IF;

// (Fiche 01, demande client) : règle absolue en pilotage couplé (both) normal --
// descente autorisée UNIQUEMENT benne ouverte, montée UNIQUEMENT benne fermée. Réutilise
// CoupledUserRequestActive/CoupledUserRequestDirection (§1) : déjà "mouvement couplé
// demandé" dans les 2 modes (joystick Select=0 exclut le pilotage unitaire M1/M2 seul,
// BtnWinchBothUp/Down exclut les boutons IHM individuels M1/M2). Jamais actif en SEMI_AUTO
// (mêmes conditions que le reste de ce §).
// coupe-circuit d'urgence (machine bloquée en butée
// M2_LimitShift). GVL_IHM.Commun.Cfg.TglEnableCoupledBucketSequencing (défaut FALSE) : si FALSE,
// ces 2 flags restent FALSE en permanence -- CmdOpen_IHM/CmdClose_IHM ne sont plus jamais armés
// par le mouvement couplé joystick, instBucket.Busy ne peut plus être déclenché QUE par action
// manuelle benne/DumpAtTremie/ExtractionSequence (comportement strictement identique à avant
// Fiche 01).
CoupledDiveBucketOpenArmed := GVL_IHM.Commun.Cfg.TglEnableCoupledBucketSequencing
    AND (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.SEMI_AUTO)
    AND CoupledUserRequestActive AND (CoupledUserRequestDirection = -1)
    AND NOT _BucketState.IsOpen;
CoupledAscentBucketCloseArmed := GVL_IHM.Commun.Cfg.TglEnableCoupledBucketSequencing
    AND (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.SEMI_AUTO)
    AND CoupledUserRequestActive AND (CoupledUserRequestDirection = 1)
    AND NOT _BucketState.IsClosed;

IF PRG_03_Modes_Cycle.Auth.Mode = E_Mode.SEMI_AUTO THEN
    // Pont SEMI_AUTO (L3) : fermeture benne pilotée par le séquenceur de cycle.
    CmdBucketCloseArbitrated := PRG_03_Modes_Cycle.instCycleSemiAuto.BucketCmd.Close;
ELSIF instExtractionSequence.BucketCloseRequest THEN
    CmdBucketCloseArbitrated := TRUE;
ELSIF CoupledAscentBucketCloseArmed THEN
    CmdBucketCloseArbitrated := TRUE;
ELSE
    CmdBucketCloseArbitrated := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnClose;
END_IF;

// urgence : instDiveSearch.KoboldMeasureEnable
// n'est TRUE que dans SEARCHING_IMMERSION/SEARCHING_BOTTOM, atteignables uniquement après
// WAIT_PRECONDITIONS (DiveStartMin_M/ImmersionUpper_M/ImmersionLower_M -- réglages pas encore
// calibrés). Avec le bypass (TglBypassDiveSearchSequence), le contacteur doit être piloté
// INDÉPENDAMMENT de ces préconditions dès qu'on descend réellement.
IF PRG_03_Modes_Cycle.Auth.Mode = E_Mode.SEMI_AUTO THEN
    // Pont SEMI_AUTO (L3) : contacteur Kobold piloté par le séquenceur de cycle.
    KoboldContactorCmdArbitrated := PRG_03_Modes_Cycle.instCycleSemiAuto.BucketCmd.KoboldContactorCmd;
ELSE
    KoboldContactorCmdArbitrated := instDiveSearch.KoboldMeasureEnable
        OR (GVL_IHM.DredgingAssist.Cmd.TglBypassDiveSearchSequence
            AND CoupledUserRequestActive AND (CoupledUserRequestDirection = -1));
END_IF;


{endregion}

{region "§2 Commande benne"}
// === 🏗️ §2 COMMANDE DU BENNE (FB_Bucket) ===

// en mode "vidage à la trémie" (MAINT_N1/N2, bit armé), une demande DOWN à
// la trémie arme l'ouverture benne au lieu de faire descendre M2 — le mouvement réel reste
// gouverné par MotionRequestActive/MotionDirection ci-dessous (rien ne bouge tant que
// l'opérateur ne pousse pas réellement DOWN) ; instBucket.Busy prend alors la main sur
// l'arbitrage M2 normal (mécanisme déjà existant, voir §3bis plus bas).
DumpAtTremieBucketOpenArmed := DumpAtTremieAssistActive AND PRG_05_Translation.M3_AtTremieStable;
GVL_IHM.DredgingAssist.State.DumpAtTremieBucketOpenArmed := DumpAtTremieBucketOpenArmed;

instBucket(
    Enable              := NOT PRG_03_Modes_Cycle.Auth.InhibitM2,
    Reset               := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged     := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                := PRG_03_Modes_Cycle.Auth.Mode,
    CmdOpen_IHM         := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnOpen OR DumpAtTremieBucketOpenArmed OR CoupledDiveBucketOpenArmed
                           OR (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.SEMI_AUTO AND PRG_03_Modes_Cycle.instCycleSemiAuto.BucketCmd.Open),
    CmdClose_IHM        := CmdBucketCloseArbitrated,
    MotionRequestActive := CoupledUserRequestActive,
    MotionDirection     := CoupledUserRequestDirection,
    CablePosM1          := PRG_02_Acquisition.CablePosM1,
    CablePosM2          := PRG_02_Acquisition.CablePosM2,
    HomedM1             := PRG_02_Acquisition.instHomingM1.Homed,
    HomedM2             := PRG_02_Acquisition.instHomingM2.Homed,
    M1_Busy             := instWinchM1.Busy,
    M2_Busy             := instWinchM2.Busy,
    ConfirmOpenPosition := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmOpenPos,
    ConfirmClosePosition:= GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmClosePos,
    Config              := _BucketCfgPersist.Config,
    CfgTimeoutDuration     := GVL_IHM.M2TreuilBenne.Bucket.Cfg.CfgTimeoutDuration,
    BucketState        := _BucketState,
    InhibitM1           := PRG_03_Modes_Cycle.Auth.InhibitM1,
    InhibitM2           := PRG_03_Modes_Cycle.Auth.InhibitM2,
    BypassGlobal        := GVL_IHM.M2TreuilBenne.Bucket.Bypass.Global
);

// / (T114) : Auto-séquencement benne & Dégradation Palier 1
// Si la benne est en cours de fermeture/ouverture (instBucket.Busy), le mouvement couplé attend.
// T114 : Si la benne n'est pas fermée (NOT IsClosed) et que instBucket n'est plus occupé (Busy=FALSE),
// toute demande de montée est automatiquement dégradée au Palier 1 (Vitesse lente, voir instWinchM1/M2),
// protégeant ainsi la mécanique même en pilotage unitaire ou si l'auto-séquencement est désactivé.
// 📌 Note d'architecture (lag 1 scan) : M1/M2LogicRequestDirection est consommé ici avant son calcul arbitré
// en §3 (lag d'un cycle automate nominal, toléré et homogène avec les arbitrages Translation/Modes).
CoupledMotionBlockedByBucket := CoupledDiveBucketOpenArmed AND NOT instBucket.Busy;
BucketNotClosedAscentStep1 := (M1LogicRequestDirection = 1 OR M2LogicRequestDirection = 1) AND NOT instBucket.Busy AND NOT _BucketState.IsClosed;

// T111 : En mode récupération (SyncEnable=FALSE), si un mou de câble est détecté (bit3 ErrorId),
// la montée/enroulement est autorisée mais bridée au Palier 1 pour retendre le tambour en sécurité.
// 📌 Note d'architecture (lag 1 scan) : instSafetyWinchM1/M2.ErrorId est consommé ici avant l'exécution du FB
// au §5bis (lag d'un cycle automate nominal, sécurisé en amont par la lecture directe de M2_TensionedCable_DI).
SlackCableAscentStep1 := NOT PRG_03_Modes_Cycle.Auth.SyncEnable AND (
    ((instSafetyWinchM1.ErrorId AND 16#0008) <> 16#0000) OR
    ((instSafetyWinchM2.ErrorId AND 16#0008) <> 16#0000) OR
    (NOT PRG_02_Acquisition.HwIn.Winch.M2_TensionedCable_DI)
);

SyncMinorDeviation := (instWinchSync.ErrorId AND 16#0001) <> 16#0000;
SyncMinorDeviationBlocksUp   := _SyncSoftStopEnable AND SyncMinorDeviation AND (instWinchSync.SignedDeltaPosM > 0.0);
SyncMinorDeviationBlocksDown := _SyncSoftStopEnable AND SyncMinorDeviation AND (instWinchSync.SignedDeltaPosM < 0.0);

IF _CommunCfgPersist.WinchMaxStepAscent <= 0 THEN
    EffectiveMaxStepAscent := 5;
ELSE
    EffectiveMaxStepAscent := _CommunCfgPersist.WinchMaxStepAscent;
END_IF;

IF _CommunCfgPersist.WinchMaxStepDescente <= 0 THEN
    EffectiveMaxStepDescente := 3;
ELSE
    EffectiveMaxStepDescente := _CommunCfgPersist.WinchMaxStepDescente;
END_IF;


{endregion}

{region "§3 Arbitrage consignes M1/M2"}
// === 🔀 §3 ARBITRAGE CONSIGNES M1 / M2 ===

IF PRG_03_Modes_Cycle.Auth.Mode = E_Mode.SEMI_AUTO THEN
    // Pont SEMI_AUTO (L3) : consomme les demandes du séquenceur de cycle.
    // FB_Cycle produit déjà StartStop conditionné par CycleMotionPermit (homme-mort 3s, D2).
    M1LogicRequestDirection := PRG_03_Modes_Cycle.instCycleSemiAuto.WinchM1Cmd.Direction;
    M1LogicRequestStartStop := PRG_03_Modes_Cycle.instCycleSemiAuto.WinchM1Cmd.StartStop;
    M1LogicRequestSpeedRef_Pct  := PRG_03_Modes_Cycle.instCycleSemiAuto.WinchM1Cmd.SpeedPct;
ELSE
    IF NOT GVL_IHM.Modes.Cmd.TglJoystickMaster THEN
        // Mode Boutons IHM
        IF GVL_IHM.Commun.BtnWinchBothUp OR GVL_IHM.M1TreuilRetenue.Cmd.BtnUp THEN
            M1LogicRequestDirection := 1;
            M1LogicRequestSpeedRef_Pct  := 100.0;
        ELSIF GVL_IHM.Commun.BtnWinchBothDown OR GVL_IHM.M1TreuilRetenue.Cmd.BtnDown THEN
            M1LogicRequestDirection := -1;
            M1LogicRequestSpeedRef_Pct  := 100.0;
        ELSE
            M1LogicRequestDirection := 0;
            M1LogicRequestSpeedRef_Pct  := 0.0;
        END_IF;
    ELSE
        // Mode Joystick Maître
        IF (PRG_03_Modes_Cycle.Auth.JoystickWinchSelectArbitrated = 0 OR PRG_03_Modes_Cycle.Auth.JoystickWinchSelectArbitrated = 1) THEN
            M1LogicRequestDirection := PRG_02_Acquisition.instJoystick.AxisCmdY.Direction;
            M1LogicRequestSpeedRef_Pct  := ABS(PRG_02_Acquisition.instJoystick.AxisCmdY.SpeedRef);
        ELSE
            M1LogicRequestDirection := 0;
            M1LogicRequestSpeedRef_Pct  := 0.0;
        END_IF;
    END_IF;

    M1LogicRequestStartStop := (M1LogicRequestDirection <> 0) AND NOT instBucket.Busy
                            AND NOT CoupledMotionBlockedByBucket
                            AND NOT ((SyncMinorDeviationBlocksUp   AND (M1LogicRequestDirection = 1))
                                 OR  (SyncMinorDeviationBlocksDown AND (M1LogicRequestDirection = -1)))
                            AND (NOT GVL_IHM.Modes.Cmd.TglJoystickMaster OR PRG_02_Acquisition.JoystickDeadmanArmed);
END_IF;

// (Fiche 01, demande client "jamais arrêter M2") : condition renforcée
// "instBucket.Busy AND instBucket.M2_StartStop" au lieu de "instBucket.Busy" seul. Sans le 2e
// terme, le scan où le benne atteint sa cible (M2_StartStop benne retombé à FALSE ce même
// scan, AVANT que Busy ne retombe le scan SUIVANT) forçait un arrêt M2 d'1 scan avant que
// l'arbitrage normal ne prenne le relais -- fenêtre de coupure dépendante du timing exact de
// la bascule Busy, pas garantie structurellement. Avec le 2e terme, ce scan tombe directement
// dans la branche ELSE (arbitrage normal) : si le mouvement couplé est toujours demandé, M2
// reçoit sa commande de continuité le MÊME scan, sans dépendre d'un timing de bascule.
IF instBucket.Busy AND instBucket.M2_StartStop THEN
    M2LogicRequestStartStop := instBucket.M2_StartStop;
    M2LogicRequestDirection := instBucket.M2_Direction;
    M2LogicRequestSpeedRef_Pct  := 15.0;
ELSE
    IF PRG_03_Modes_Cycle.Auth.Mode = E_Mode.SEMI_AUTO THEN
        // Pont SEMI_AUTO (L3) : consomme les demandes du séquenceur de cycle.
        M2LogicRequestDirection := PRG_03_Modes_Cycle.instCycleSemiAuto.WinchM2Cmd.Direction;
        M2LogicRequestStartStop := PRG_03_Modes_Cycle.instCycleSemiAuto.WinchM2Cmd.StartStop;
        M2LogicRequestSpeedRef_Pct  := PRG_03_Modes_Cycle.instCycleSemiAuto.WinchM2Cmd.SpeedPct;
    ELSE
        IF NOT GVL_IHM.Modes.Cmd.TglJoystickMaster THEN
            // Mode Boutons IHM
            IF GVL_IHM.Commun.BtnWinchBothUp OR GVL_IHM.M2TreuilBenne.Cmd.BtnUp THEN
                M2LogicRequestDirection := 1;
                M2LogicRequestSpeedRef_Pct  := 100.0;
            ELSIF GVL_IHM.Commun.BtnWinchBothDown OR GVL_IHM.M2TreuilBenne.Cmd.BtnDown THEN
                M2LogicRequestDirection := -1;
                M2LogicRequestSpeedRef_Pct  := 100.0;
            ELSE
                M2LogicRequestDirection := 0;
                M2LogicRequestSpeedRef_Pct  := 0.0;
            END_IF;
        ELSE
            // Mode Joystick Maître
            IF (PRG_03_Modes_Cycle.Auth.JoystickWinchSelectArbitrated = 0 OR PRG_03_Modes_Cycle.Auth.JoystickWinchSelectArbitrated = 2) THEN
                M2LogicRequestDirection := PRG_02_Acquisition.instJoystick.AxisCmdY.Direction;
                M2LogicRequestSpeedRef_Pct  := ABS(PRG_02_Acquisition.instJoystick.AxisCmdY.SpeedRef);
            ELSE
                M2LogicRequestDirection := 0;
                M2LogicRequestSpeedRef_Pct  := 0.0;
            END_IF;
        END_IF;

        M2LogicRequestStartStop := (M2LogicRequestDirection <> 0)
                                AND NOT CoupledMotionBlockedByBucket
                                AND NOT ((SyncMinorDeviationBlocksUp   AND (M2LogicRequestDirection = -1))
                                     OR  (SyncMinorDeviationBlocksDown AND (M2LogicRequestDirection = 1)))
                                AND (NOT GVL_IHM.Modes.Cmd.TglJoystickMaster OR PRG_02_Acquisition.JoystickDeadmanArmed);
    END_IF;
END_IF;

// (Fiche 01, demande client "jamais arrêter M2") : 2e mécanisme de coupure trouvé
// en plus de celui déjà corrigé §3 ci-dessus -- celui-ci forçait un arrêt INCONDITIONNEL de M1
// ET M2 à CHAQUE fin d'action benne (Busy retombé), y compris pendant un enchaînement
// ouverture/fermeture-puis-mouvement-couplé où le mouvement doit continuer sans coupure
// (affecte aussi ExtractionSequence.CLOSING_BUCKET->CONTROL_ASCENT, pas seulement la Fiche 01).
// Corrigé : ne force plus l'arrêt si un mouvement couplé est toujours activement demandé
// (CoupledUserRequestActive), auquel cas l'arbitrage normal (§3, déjà corrigé) prend le
// relais sans interruption. Comportement inchangé pour toute fin d'action benne SANS mouvement
// couplé en cours (ouverture/fermeture manuelle isolée, bouton IHM) : l'arrêt reste forcé.
BenneBusyFallEdge(CLK := instBucket.Busy);
IF BenneBusyFallEdge.Q AND NOT (CoupledUserRequestActive AND (CoupledUserRequestDirection <> 0)) THEN
    M1LogicRequestStartStop := FALSE;
    M2LogicRequestStartStop := FALSE;
END_IF;

// (Fiche 01, demande client) : après une fermeture benne armée PAR CE mécanisme
// (pas ExtractionSequence, qui a déjà sa propre phase CONTROL_ASCENT), la montée couplée qui
// enchaîne démarre en vitesse contrôlée (palier 1) sur ExtractionControlDistance_M (paramètre
// existant, réutilisé -- pas de nouveau réglage) avant de repasser en paliers normaux.
BucketBusyRiseEdge(CLK := instBucket.Busy);
IF BucketBusyRiseEdge.Q THEN
    ControlAscentArmedForThisClose := CoupledAscentBucketCloseArmed;
END_IF;
IF BucketBusyFallEdge.Q AND ControlAscentArmedForThisClose THEN
    ControlAscentActive := TRUE;
    ControlAscentStartM1PosM := PRG_02_Acquisition.CablePosM1;
    ControlAscentStartM2PosM := PRG_02_Acquisition.CablePosM2;
END_IF;
IF ControlAscentActive THEN
    IF (ABS(PRG_02_Acquisition.CablePosM1 - ControlAscentStartM1PosM) >= GVL_IHM.DredgingAssist.Cfg.ExtractionControlDistance_M)
       AND (ABS(PRG_02_Acquisition.CablePosM2 - ControlAscentStartM2PosM) >= GVL_IHM.DredgingAssist.Cfg.ExtractionControlDistance_M) THEN
        ControlAscentActive := FALSE;             // Distance de contrôle parcourue : paliers normaux
    ELSIF NOT (CoupledUserRequestActive AND (CoupledUserRequestDirection = 1)) THEN
        ControlAscentActive := FALSE;             // Montée relâchée/interrompue : annule la phase
    END_IF;
END_IF;


{endregion}

{region "§4 Synchronisation M1/M2"}
// === 🔄 §4 SYNCHRONISATION M1 / M2 ===

instWinchSync(
    Enable          := PRG_03_Modes_Cycle.Auth.SyncEnable AND NOT instBucket.Busy
                        AND NOT PRG_03_Modes_Cycle.Auth.InhibitM1 AND NOT PRG_03_Modes_Cycle.Auth.InhibitM2,
    Reset           := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode            := PRG_03_Modes_Cycle.Auth.Mode,
    CablePosM1      := PRG_02_Acquisition.CablePosM1,
    CablePosM2      := PRG_02_Acquisition.CablePosM2,
    HomedM1         := PRG_02_Acquisition.instHomingM1.Homed,
    HomedM2         := PRG_02_Acquisition.instHomingM2.Homed,
    SyncEnable      := PRG_03_Modes_Cycle.Auth.SyncEnable,
    CfgSyncToleranceM  := _SyncCfgPersist.CfgSyncTolerance_M,
    ActiveOffsetM   := instBucket.ActiveOffsetM,
    RelayFwdM1      := instWinchM1.RelayFwd,
    RelayFwdM2      := instWinchM2.RelayFwd,
    RelayRevM1      := instWinchM1.RelayRev,
    RelayRevM2      := instWinchM2.RelayRev,
    Contactor1_M1   := instWinchM1.Contactor1,
    Contactor1_M2   := instWinchM2.Contactor1,
    Contactor2_M1   := instWinchM1.Contactor2,
    Contactor2_M2   := instWinchM2.Contactor2,
    Contactor3_M1   := instWinchM1.Contactor3,
    Contactor3_M2   := instWinchM2.Contactor3,
    Contactor4_M1   := instWinchM1.Contactor4,
    Contactor4_M2   := instWinchM2.Contactor4,
    BypassGlobal    := GVL_IHM.M1M2Sync.Bypass.Global
);

IF instBucket.M2_ForceSlowSpeed THEN
    M2_SpeedStepTableActive.P1R1 := _WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P1R2 := _WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P1R3 := _WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P1R4 := _WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.P2R1 := _WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P2R2 := _WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P2R3 := _WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P2R4 := _WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.P3R1 := _WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P3R2 := _WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P3R3 := _WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P3R4 := _WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.P4R1 := _WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P4R2 := _WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P4R3 := _WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P4R4 := _WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.P5R1 := _WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P5R2 := _WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P5R3 := _WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P5R4 := _WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.StepThreshold_Pct := _WinchSpeedStepTable.StepThreshold_Pct;
ELSE
    M2_SpeedStepTableActive := _WinchSpeedStepTable;
END_IF;


{endregion}

{region "§5 Couplage croise et securites"}
// === 🛑 §5 COUPLAGE CROISÉ & SÉCURITÉS ===

// (demande client) : la limite légale (profondeur min. autorisée) doit elle aussi
// bénéficier du ralentissement progressif avant arrêt (comme la limite câble physique), pas juste
// un arrêt sec (DescendPermit, ajouté au lot précédent). Comme les 2 limites bornent la même
// direction (descente), on alimente FB_Winch.BottomLimitM avec la PLUS RESTRICTIVE des deux
// (MAX de 2 valeurs négatives = celle la moins profonde = atteinte en premier) : le ralentissement
// (FB_Winch §"RALENTISSEMENT AUTOMATIQUE SUR BORDURES") s'enclenche alors sur la bonne limite,
// légale ou câble, sans dupliquer le mécanisme.
IF _CommunCfgPersist.LimitLegalEnabled THEN
    BottomLimitM1_Active := MAX(_WinchM1CfgPersist.CfgCableLimitDescent_M, _CommunCfgPersist.LimitLegalDepthMinAllowed_M);
    BottomLimitM2_Active := MAX(_WinchM2CfgPersist.CfgCableLimitDescent_M, _CommunCfgPersist.LimitLegalDepthMinAllowed_M);
ELSE
    BottomLimitM1_Active := _WinchM1CfgPersist.CfgCableLimitDescent_M;
    BottomLimitM2_Active := _WinchM2CfgPersist.CfgCableLimitDescent_M;
END_IF;

// 🩺 InputModuleFault (AF06 §3bis) : un module DI TOR hors service rend indisponibles
// les retours frein/thermique/contacteurs/fin de course des DEUX treuils (VH_0800END,
// Local_Digital_IO) — pas de granularité par treuil possible, donc SafeStop des DEUX.
SafeStopM1_Raw      := ((instWinchSync.ErrorId AND 16#0002) <> 16#0000) OR instBucket.M1SlipDetected OR PRG_02_Acquisition.InputModuleFault;
SafeStopM2_Raw      := ((instWinchSync.ErrorId AND 16#0002) <> 16#0000) OR PRG_02_Acquisition.InputModuleFault;

// FICHE 05 — Surveillance Kobold descente normale (hors FB_DiveSearch)
// : "HwIn.Winch.M1M2_KoboldImmersed_DI" n'existe
// pas (ST_HwWinch n'a pas ce membre) -- corrigé vers le meme signal deja utilise par
// instDiveSearch ci-dessus (§1, ligne KoboldImmersed), HwIn.Machine.M1_M2_KoboldBottomTouch_DI.
KoboldAutoStopRiseEdge(CLK := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI);
KoboldAutoStopFallEdge(CLK := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI);

// Levée du verrou au neutre du joystick/boutons ou si toggle désactivé
IF PRG_02_Acquisition.instJoystick.AtNeutral OR NOT GVL_IHM.Commun.Cfg.TglEnableKoboldAutoStopDescent THEN
    KoboldImmersionConfirmed := FALSE;
    KoboldBottomTouchLatched := FALSE;
END_IF;

// (revue Fiche 05) : CoupledUserRequestActive ajouté -- sans lui, cette
// surveillance pouvait s'armer aussi en pilotage UNITAIRE M1 (Select=1), où CoupledUserRequestDirection
// reflète quand même l'axe joystick brut (seul CoupledUserRequestActive exige Select=0).
// Hors scope de la fiche ("pendant une descente COUPLÉE normale") -- corrigé.
// Qualification immersion : front montant Kobold dans la fenêtre [ImmersionLower_M..ImmersionUpper_M]
IF GVL_IHM.Commun.Cfg.TglEnableKoboldAutoStopDescent
   AND CoupledUserRequestActive
   AND (CoupledUserRequestDirection = -1)
   AND _BucketState.IsOpen
   AND KoboldAutoStopRiseEdge.Q THEN
    IF (PRG_02_Acquisition.CablePosM1 <= _DredgingAssistCfgPersist.ImmersionUpper_M)
       AND (PRG_02_Acquisition.CablePosM1 >= _DredgingAssistCfgPersist.ImmersionLower_M)
       AND (PRG_02_Acquisition.CablePosM2 <= _DredgingAssistCfgPersist.ImmersionUpper_M)
       AND (PRG_02_Acquisition.CablePosM2 >= _DredgingAssistCfgPersist.ImmersionLower_M) THEN
        KoboldImmersionConfirmed := TRUE;
    END_IF;
END_IF;

// Détection fond : front descendant Kobold APRÈS immersion confirmée
IF KoboldAutoStopFallEdge.Q AND KoboldImmersionConfirmed THEN
    KoboldBottomTouchLatched := TRUE;
    KoboldImmersionConfirmed := FALSE;
END_IF;

// GAP RÉEL CONFIRMÉ : instDiveSearch.DescendPermit
// était calculé (FB_DiveSearch.st) mais JAMAIS consommé nulle part dans PRG_04/PRG_06 -- en
// mode Dive actif, rien n'empêchait réellement de descendre benne fermée, malgré la précondition
// FB_DiveSearch (BucketIsOpen requis pour READY_TO_DESCEND). Ajouté : autorisation directe et
// explicite, gardée par instDiveSearch.Enable (mode Dive réellement actif) -- indépendante du
// timing interne DescendPermit. Bloque uniquement si benne PAS confirmée ouverte.
DescendPermitDiveBucketOpen := NOT (instDiveSearch.Enable AND CoupledUserRequestActive
    AND (CoupledUserRequestDirection = -1) AND NOT _BucketState.IsOpen);

// : BypassKoboldBottomTouched confirmait le fond
// (pour Extraction) mais ne bloquait pas la descente elle-même -- seul KoboldBottomTouchLatched
// (mécanisme Fiche 05 séparé) le faisait. Ajouté : le bypass arrête aussi la descente
// instantanément, même doctrine que le mécanisme Fiche 05.
// demande client : mode "pilotage unitaire M2 sécurisé"
// (SelJoystickWinch=2 + toggle IHM). Ne passe PAS par instBucket (pas de CloseReq/OpenReq
// mémorisé, jogging libre) -- bornes directes ouvert/fermé (mêmes offsets que FB_Bucket,
// relatifs à la position réelle de M1) + palier 1 (voir instWinchM2 §6 plus bas).
ManualBucketLimitsActive := GVL_IHM.M2TreuilBenne.Bucket.Cmd.TglManualBucketLimits
    AND (PRG_03_Modes_Cycle.Auth.JoystickWinchSelectArbitrated = 2);

DescendPermitM1_Raw := NOT (KoboldBottomTouchLatched OR BypassKoboldBottomTouched) AND DescendPermitDiveBucketOpen;
// (21bis) — DÉPASSEMENT CONFIRMÉ : ce chemin (pilotage
// unitaire M2, hors instBucket) n'avait AUCUNE anticipation d'inertie, contrairement au CASE
// BUSY de FB_Bucket -- même OpenAnticipationM/CloseAnticipationM réutilisé ici
// pour couvrir aussi le jog unitaire.
DescendPermitM2_Raw := NOT (KoboldBottomTouchLatched OR BypassKoboldBottomTouched) AND DescendPermitDiveBucketOpen
    AND NOT (ManualBucketLimitsActive AND (PRG_02_Acquisition.CablePosM2 <= (PRG_02_Acquisition.CablePosM1 + _BucketCfgPersist.Config.OffsetOpenM + _BucketCfgPersist.Config.OpenAnticipationM)));

M2_LimitShift := SEL(_BucketState.IsClosed OR instBucket.CloseReq OR (PRG_03_Modes_Cycle.Auth.JoystickWinchSelectArbitrated = 2),
                      0.0,
                      (PRG_02_Acquisition.CablePosM1 + _BucketCfgPersist.Config.OffsetCloseM + 0.5)
                      - _WinchM2CfgPersist.CfgCableLimitAscent_M);

// : FB_Safety_Winch M1/M2 — 0 mécanisme actif avant ce lot.
// Instancié avant instWinchM1/M2 : MovementCommanded lit RelayFwd/RelayRev du scan précédent
// (même lag 1 scan accepté que M4/Translation, jamais sur Reset/SafeStop/PowerCutOff/sortie finale).
instSafetyWinchM1(
    Enable                 := StubMachineEnableN1 AND (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE) AND NOT PRG_03_Modes_Cycle.Auth.InhibitM1,
    Reset                  := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged  := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                   := PRG_03_Modes_Cycle.Auth.Mode,
    SyncEnable             := PRG_03_Modes_Cycle.Auth.SyncEnable,
    JoystickOnline         := PRG_07_Supervision.instDiagCanOpen.DeviceJoystick.Online,
    JoystickOperational    := PRG_07_Supervision.instDiagCanOpen.DeviceJoystick.Operational,
    HeartbeatIhmOk         := GVL_IHM.Commun.HeartbeatIhmOk,
    EncoderAvailable       := PRG_02_Acquisition.instEncoderAbsM1.EncoderAvailable,
    EncoderFaultBypass     := GVL_IHM.M1TreuilRetenue.Bypass.EncoderFault,
    ThermalFeedback        := NOT PRG_02_Acquisition.HwIn.Winch.M1_ThermalOk_DI,
    BrakeThermalFeedback   := NOT PRG_02_Acquisition.HwIn.Machine.M1_M2_M3_BrakeThermalOk_DI,
    SlackCableDetected     := NOT PRG_02_Acquisition.HwIn.Winch.M2_TensionedCable_DI,
    PhaseRotationOk        := PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI,
    TopPositionSensor      := PRG_02_Acquisition.HwIn.Winch.M1M2_TopPositionFree_DI,
    InReferencingMode      := PRG_02_Acquisition.instHomingM1.Busy,
    CablePosM              := PRG_02_Acquisition.CablePosM1,
    CfgCableLimitDescentM  := _WinchM1CfgPersist.CfgCableLimitDescent_M,
    LimitLegalReached      := GVL_IHM.Commun.LimitLegalReached,
    Direction              := M1LogicRequestDirection,
    MovementCommanded      := instWinchM1.RelayFwd OR instWinchM1.RelayRev,
    Homed                  := PRG_02_Acquisition.instHomingM1.Homed,
    HomingSuspect          := PRG_02_Acquisition.instHomingM1.HomingSuspect,
    TopLimitM              := _WinchM1CfgPersist.CfgCableLimitAscent_M,
    FwdRevSpeedFeedbackOff := PRG_02_Acquisition.HwIn.Winch.M1_ContactorsReleased_DI,
    BrakeFeedback          := PRG_02_Acquisition.HwIn.Winch.M1_BrakeIsOpen_DI,
    JoystickYNeutral       := PRG_02_Acquisition.JoystickYNeutral,
    BenneHoldStillActive   := instBucket.Busy,
    ExpectedOtherWinchPosM := PRG_02_Acquisition.CablePosM2 - instBucket.ActiveOffsetM,
    BenneBusy              := instBucket.Busy,
    OtherWinchInhibited    := PRG_03_Modes_Cycle.Auth.InhibitM2,
    MeasuredSpeedMps       := PRG_02_Acquisition.M1_Speed_Mps,
    MeasuredSpeedSignedMps := PRG_02_Acquisition.M1_SignedSpeed_Mps,
    MeasuredSpeedValid     := PRG_02_Acquisition.M1_SpeedValid,
    BypassGlobal           := GVL_IHM.M1TreuilRetenue.Bypass.Global,
    BypassSafety           := GVL_IHM.M1TreuilRetenue.Bypass.Safety,
    BypassProcess          := GVL_IHM.M1TreuilRetenue.Bypass.Process,
    // (demande client) : OR avec le bypass commun (Commun.Bypass) -- leve la
    // protection sur les 2 treuils simultanement pour le pilotage "both", sans retirer le
    // bypass individuel pour le pilotage a l'unite.
    // 🔒 SÉCURITÉ : GVL_Simulation.SimulationBypassActive n'agit QUE si SimulationModeActive=TRUE (strictement inopérant sur machine réelle).
    BypassTopLimitSwitch   := GVL_IHM.M1TreuilRetenue.Bypass.TopLimitSwitch OR GVL_IHM.Commun.Bypass.TopLimitSwitch
                              OR PRG_02_Acquisition.SimulationBypassActive,
    BypassTopLimitSoftware := GVL_IHM.M1TreuilRetenue.Bypass.TopLimitSoftware OR GVL_IHM.Commun.Bypass.TopLimitSoftware
                              OR PRG_02_Acquisition.SimulationBypassActive,
    BypassCableLimitSwitch := GVL_IHM.M1TreuilRetenue.Bypass.CableLimitSwitch OR GVL_IHM.Commun.Bypass.CableLimitSwitch,
    BypassLimitLegal       := GVL_IHM.M1TreuilRetenue.Bypass.LimitLegal OR GVL_IHM.Commun.Bypass.LimitLegal
                              OR PRG_02_Acquisition.SimulationBypassActive,
    BypassOperatorComm     := GVL_IHM.M1TreuilRetenue.Bypass.OperatorComm,
    BypassPhaseRotation    := GVL_IHM.M1TreuilRetenue.Bypass.PhaseRotation,
    BypassBrakeThermal     := GVL_IHM.M1TreuilRetenue.Bypass.BrakeThermal,
    BypassMotorThermal     := GVL_IHM.M1TreuilRetenue.Bypass.MotorThermal,
    BypassMecaA            := GVL_IHM.M1TreuilRetenue.Bypass.MecaA,
    BypassMecaB            := GVL_IHM.M1TreuilRetenue.Bypass.MecaB,
    BypassMecaC            := GVL_IHM.M1TreuilRetenue.Bypass.MecaC,
    BypassMecaD            := GVL_IHM.M1TreuilRetenue.Bypass.MecaD,
    BypassMecaE            := GVL_IHM.M1TreuilRetenue.Bypass.MecaE
);

instSafetyWinchM2(
    Enable                 := StubMachineEnableN1 AND (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE) AND NOT PRG_03_Modes_Cycle.Auth.InhibitM2,
    Reset                  := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged  := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                   := PRG_03_Modes_Cycle.Auth.Mode,
    SyncEnable             := PRG_03_Modes_Cycle.Auth.SyncEnable,
    JoystickOnline         := PRG_07_Supervision.instDiagCanOpen.DeviceJoystick.Online,
    JoystickOperational    := PRG_07_Supervision.instDiagCanOpen.DeviceJoystick.Operational,
    HeartbeatIhmOk         := GVL_IHM.Commun.HeartbeatIhmOk,
    EncoderAvailable       := PRG_02_Acquisition.instEncoderAbsM2.EncoderAvailable,
    EncoderFaultBypass     := GVL_IHM.M2TreuilBenne.Bypass.EncoderFault,
    ThermalFeedback        := NOT PRG_02_Acquisition.HwIn.Winch.M2_ThermalOk_DI,
    BrakeThermalFeedback   := NOT PRG_02_Acquisition.HwIn.Machine.M1_M2_M3_BrakeThermalOk_DI,
    SlackCableDetected     := NOT PRG_02_Acquisition.HwIn.Winch.M2_TensionedCable_DI,
    PhaseRotationOk        := PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI,
    TopPositionSensor      := PRG_02_Acquisition.HwIn.Winch.M1M2_TopPositionFree_DI,
    InReferencingMode      := PRG_02_Acquisition.instHomingM2.Busy,
    CablePosM              := PRG_02_Acquisition.CablePosM2,
    CfgCableLimitDescentM  := _WinchM2CfgPersist.CfgCableLimitDescent_M,
    LimitLegalReached      := GVL_IHM.Commun.LimitLegalReached,
    Direction              := M2LogicRequestDirection,
    MovementCommanded      := instWinchM2.RelayFwd OR instWinchM2.RelayRev,
    Homed                  := PRG_02_Acquisition.instHomingM2.Homed,
    HomingSuspect          := PRG_02_Acquisition.instHomingM2.HomingSuspect,
    TopLimitM              := _WinchM2CfgPersist.CfgCableLimitAscent_M + M2_LimitShift,
    FwdRevSpeedFeedbackOff := PRG_02_Acquisition.HwIn.Winch.M2_ContactorsReleased_DI,
    BrakeFeedback          := PRG_02_Acquisition.HwIn.Winch.M2_BrakeIsOpen_DI,
    JoystickYNeutral       := PRG_02_Acquisition.JoystickYNeutral,
    BenneHoldStillActive   := FALSE,
    ExpectedOtherWinchPosM := PRG_02_Acquisition.CablePosM1 + instBucket.ActiveOffsetM,
    BenneBusy              := instBucket.Busy,
    OtherWinchInhibited    := PRG_03_Modes_Cycle.Auth.InhibitM1,
    MeasuredSpeedMps       := PRG_02_Acquisition.M2_Speed_Mps,
    MeasuredSpeedSignedMps := PRG_02_Acquisition.M2_SignedSpeed_Mps,
    MeasuredSpeedValid     := PRG_02_Acquisition.M2_SpeedValid,
    BypassGlobal           := GVL_IHM.M2TreuilBenne.Bypass.Global,
    BypassSafety           := GVL_IHM.M2TreuilBenne.Bypass.Safety,
    BypassProcess          := GVL_IHM.M2TreuilBenne.Bypass.Process,
    // OR avec le bypass commun (Commun.Bypass) -- voir M1 ci-dessus
    // 🔒 SÉCURITÉ : GVL_Simulation.SimulationBypassActive n'agit QUE si SimulationModeActive=TRUE (strictement inopérant sur machine réelle).
    BypassTopLimitSwitch   := GVL_IHM.M2TreuilBenne.Bypass.TopLimitSwitch OR GVL_IHM.Commun.Bypass.TopLimitSwitch
                              OR PRG_02_Acquisition.SimulationBypassActive,
    BypassTopLimitSoftware := GVL_IHM.M2TreuilBenne.Bypass.TopLimitSoftware OR GVL_IHM.Commun.Bypass.TopLimitSoftware
                              OR PRG_02_Acquisition.SimulationBypassActive,
    BypassCableLimitSwitch := GVL_IHM.M2TreuilBenne.Bypass.CableLimitSwitch OR GVL_IHM.Commun.Bypass.CableLimitSwitch,
    BypassLimitLegal       := GVL_IHM.M2TreuilBenne.Bypass.LimitLegal OR GVL_IHM.Commun.Bypass.LimitLegal
                              OR PRG_02_Acquisition.SimulationBypassActive,
    BypassOperatorComm     := GVL_IHM.M2TreuilBenne.Bypass.OperatorComm,
    BypassPhaseRotation    := GVL_IHM.M2TreuilBenne.Bypass.PhaseRotation,
    BypassBrakeThermal     := GVL_IHM.M2TreuilBenne.Bypass.BrakeThermal,
    BypassMotorThermal     := GVL_IHM.M2TreuilBenne.Bypass.MotorThermal,
    BypassMecaA            := GVL_IHM.M2TreuilBenne.Bypass.MecaA,
    BypassMecaB            := GVL_IHM.M2TreuilBenne.Bypass.MecaB,
    BypassMecaC            := GVL_IHM.M2TreuilBenne.Bypass.MecaC,
    BypassMecaD            := GVL_IHM.M2TreuilBenne.Bypass.MecaD,
    BypassMecaE            := GVL_IHM.M2TreuilBenne.Bypass.MecaE
);

SafeStopM1_Raw := SafeStopM1_Raw OR instSafetyWinchM1.SafeStop;
SafeStopM2_Raw := SafeStopM2_Raw OR instSafetyWinchM2.SafeStop;
DescendPermitM1_Raw := DescendPermitM1_Raw AND instSafetyWinchM1.DescendPermit;
DescendPermitM2_Raw := DescendPermitM2_Raw AND instSafetyWinchM2.DescendPermit;

// (mode "vidage à la trémie", demande client) : descente M1 ET M2 interdite tant
// que M3 n'est pas à P1 (travail) ou en position Maintenance -- verrouille la séquence
// descente-treuil / translation pour se rapprocher d'un enchaînement automatique sûr.
GVL_IHM.DredgingAssist.State.DumpAtTremieDescentLocked :=
    DumpAtTremieAssistActive AND NOT (PRG_05_Translation.M3_AtP1Stable OR PRG_05_Translation.M3_AtMaintenanceStable);
IF GVL_IHM.DredgingAssist.State.DumpAtTremieDescentLocked THEN
    DescendPermitM1_Raw := FALSE;
    DescendPermitM2_Raw := FALSE;
END_IF;
AscentPermitM1_Raw  := instSafetyWinchM1.AscentPermit;
AscentPermitM2_Raw  := instSafetyWinchM2.AscentPermit
    // Même anticipation que DescendPermitM2_Raw ci-dessus.
    AND NOT (ManualBucketLimitsActive AND (PRG_02_Acquisition.CablePosM2 >= (PRG_02_Acquisition.CablePosM1 + _BucketCfgPersist.Config.OffsetCloseM - _BucketCfgPersist.Config.CloseAnticipationM)));

SafeStopM1_Active      := SafeStopM1_Raw      OR (instWinchSync.SyncActive AND SafeStopM2_Raw);
SafeStopM2_Active      := SafeStopM2_Raw      OR (instWinchSync.SyncActive AND SafeStopM1_Raw);
DescendPermitM1_Active := DescendPermitM1_Raw AND (NOT instWinchSync.SyncActive OR DescendPermitM2_Raw);
DescendPermitM2_Active := DescendPermitM2_Raw AND (NOT instWinchSync.SyncActive OR DescendPermitM1_Raw);
AscentPermitM1_Active  := AscentPermitM1_Raw  AND (NOT instWinchSync.SyncActive OR AscentPermitM2_Raw);
AscentPermitM2_Active  := AscentPermitM2_Raw  AND (NOT instWinchSync.SyncActive OR AscentPermitM1_Raw);


{endregion}

{region "§6 Execution treuils M1/M2"}
// === ⚙️ §6 EXÉCUTION FB_Winch (M1 & M2) ===

instWinchM1(
    Enable                  := StubMachineEnableN1 AND (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE) AND NOT PRG_03_Modes_Cycle.Auth.InhibitM1,
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                    := PRG_03_Modes_Cycle.Auth.Mode,
    StartStop               := M1LogicRequestStartStop,
    SafeStop                := SafeStopM1_Active,
    DescendPermit           := DescendPermitM1_Active,
    AscentPermit            := AscentPermitM1_Active,
    Direction               := M1LogicRequestDirection,
    SpeedRefPct             := M1LogicRequestSpeedRef_Pct,
    SpeedStepTable          := _WinchSpeedStepTable,
    CfgMaxStepDescente      := SEL(instWinchSync.SyncDegradedStep1, EffectiveMaxStepDescente, 1),
    // (T111 / T113 / T114) : Plafonnement au Palier 1 pour mou de câble, synchro dégradée et benne non fermée
    MaxStepAscent           := SEL(instExtractionSequence.ForceMinSpeedStep OR ControlAscentActive OR instWinchSync.SyncDegradedStep1 OR BucketNotClosedAscentStep1 OR SlackCableAscentStep1, EffectiveMaxStepAscent, 1),
    MeasuredSpeedBand       := 0,
    SpeedGuardEnable        := SpeedGuardEnableM1,
    SpeedGuardReady         := NOT instWinchSync.Error,
    HomingApproachActive    := PRG_03_Modes_Cycle.Auth.HomingApproachEnable,
    FwdRevSpeedFeedbackOff  := PRG_02_Acquisition.HwIn.Winch.M1_ContactorsReleased_DI,
    BypassContactorCheck    := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.ContactorFeedback,
    Homed                   := PRG_02_Acquisition.instHomingM1.Homed,
    HomingSuspect           := PRG_02_Acquisition.instHomingM1.HomingSuspect,
    CablePosM               := PRG_02_Acquisition.CablePosM1,
    TopLimitM               := _WinchM1CfgPersist.CfgCableLimitAscent_M,
    BottomLimitM            := BottomLimitM1_Active,
    CfgSlowdownDistanceM    := _CommunCfgPersist.WinchSlowdownDistance_M,
    CfgSlowdownMaxStep      := _CommunCfgPersist.WinchSlowdownMaxStep,
    BypassGlobal            := GVL_IHM.M1TreuilRetenue.Bypass.Global
);

instWinchM2(
    Enable                  := StubMachineEnableN1 AND (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE) AND NOT PRG_03_Modes_Cycle.Auth.InhibitM2,
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                    := PRG_03_Modes_Cycle.Auth.Mode,
    StartStop               := M2LogicRequestStartStop,
    SafeStop                := SafeStopM2_Active,
    DescendPermit           := DescendPermitM2_Active,
    AscentPermit            := AscentPermitM2_Active,
    Direction               := M2LogicRequestDirection,
    SpeedRefPct             := M2LogicRequestSpeedRef_Pct,
    SpeedStepTable          := M2_SpeedStepTableActive,
    // GAP CONFIRMÉ : instBucket.M2_ForceSlowSpeed
    // ("Bloque les contacteurs de vitesse de M2", commentaire FB_Bucket.st) n'était consommé que
    // pour substituer M2_SpeedStepTableActive -- ne plafonnait PAS réellement le palier autorisé
    // pendant CLOSING_BUCKET/ouverture benne. MaxStepAscent forçait déjà palier 1 pour
    // CONTROL_ASCENT (ForceMinSpeedStep) mais pas pendant le mouvement benne lui-même ;
    // CfgMaxStepDescente n'avait AUCUN plafond, jamais. Corrigé : les deux suivent maintenant
    // instBucket.M2_ForceSlowSpeed en plus des conditions existantes.
    // (T113) : instWinchSync.SyncDegradedStep1 dégrade M2 au Palier 1 sur écart modéré.
    // (T114 / T111) : BucketNotClosedAscentStep1 et SlackCableAscentStep1 dégradent la montée au Palier 1.
    CfgMaxStepDescente      := SEL(instBucket.M2_ForceSlowSpeed OR ManualBucketLimitsActive OR instWinchSync.SyncDegradedStep1, EffectiveMaxStepDescente, 1),
    MaxStepAscent           := SEL(instExtractionSequence.ForceMinSpeedStep OR ControlAscentActive OR instBucket.M2_ForceSlowSpeed OR ManualBucketLimitsActive OR instWinchSync.SyncDegradedStep1 OR BucketNotClosedAscentStep1 OR SlackCableAscentStep1, EffectiveMaxStepAscent, 1),
    MeasuredSpeedBand       := 0,
    SpeedGuardEnable        := SpeedGuardEnableM2,
    SpeedGuardReady         := NOT instWinchSync.Error,
    HomingApproachActive    := PRG_03_Modes_Cycle.Auth.HomingApproachEnable,
    FwdRevSpeedFeedbackOff  := PRG_02_Acquisition.HwIn.Winch.M2_ContactorsReleased_DI,
    BypassContactorCheck    := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.ContactorFeedback,
    Homed                   := PRG_02_Acquisition.instHomingM2.Homed,
    HomingSuspect           := PRG_02_Acquisition.instHomingM2.HomingSuspect,
    CablePosM               := PRG_02_Acquisition.CablePosM2,
    TopLimitM               := _WinchM2CfgPersist.CfgCableLimitAscent_M + M2_LimitShift,
    BottomLimitM            := BottomLimitM2_Active,
    CfgSlowdownDistanceM    := _CommunCfgPersist.WinchSlowdownDistance_M,
    CfgSlowdownMaxStep      := _CommunCfgPersist.WinchSlowdownMaxStep,
    BypassGlobal            := GVL_IHM.M2TreuilBenne.Bypass.Global
);


{endregion}

{region "§7 Publication demandes brutes"}
// === 📤 §7 PUBLICATION DEMANDES BRUTES (WinchM1/M2FinalInterlockRequest) ===

WinchM1FinalInterlockRequest.Enable := StubMachineEnableN1;
WinchM1FinalInterlockRequest.Reset := PRG_07_Supervision.FaultMachineReset_IHM;
WinchM1FinalInterlockRequest.PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI;
WinchM1FinalInterlockRequest.SafeStop := SafeStopM1_Active;
// (retrait FB_Brake, demande client) : plus de BrakeReleaseRequest/
// BrakeCommandOpenConfirmed calcules par FB_Winch — la barriere finale
// (FB_WinchOutputInterlock_LD) recoit desormais le retour PHYSIQUE brut directement,
// et calcule elle-meme BrakeCmd := RelayFwd OR RelayRev (voir bandeau de ce FB).
WinchM1FinalInterlockRequest.BrakeFeedback := PRG_02_Acquisition.HwIn.Winch.M1_BrakeIsOpen_DI;
WinchM1FinalInterlockRequest.FwdRevSpeedFeedbackOff := PRG_02_Acquisition.HwIn.Winch.M1_ContactorsReleased_DI;
WinchM1FinalInterlockRequest.RequestedRelayFwd := instWinchM1.RelayFwd;
WinchM1FinalInterlockRequest.RequestedRelayRev := instWinchM1.RelayRev;
WinchM1FinalInterlockRequest.RequestedContactor1 := instWinchM1.Contactor1;
WinchM1FinalInterlockRequest.RequestedContactor2 := instWinchM1.Contactor2;
WinchM1FinalInterlockRequest.RequestedContactor3 := instWinchM1.Contactor3;
WinchM1FinalInterlockRequest.RequestedContactor4 := instWinchM1.Contactor4;
WinchM1FinalInterlockRequest.RequestedStep := instWinchM1.StepNumber;
WinchM1FinalInterlockRequest.PowerCutOff := instSafetyWinchM1.PowerCutOff;

WinchM2FinalInterlockRequest.Enable := StubMachineEnableN1;
WinchM2FinalInterlockRequest.Reset := PRG_07_Supervision.FaultMachineReset_IHM;
WinchM2FinalInterlockRequest.PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI;
WinchM2FinalInterlockRequest.SafeStop := SafeStopM2_Active;
WinchM2FinalInterlockRequest.BrakeFeedback := PRG_02_Acquisition.HwIn.Winch.M2_BrakeIsOpen_DI;
WinchM2FinalInterlockRequest.FwdRevSpeedFeedbackOff := PRG_02_Acquisition.HwIn.Winch.M2_ContactorsReleased_DI;
WinchM2FinalInterlockRequest.RequestedRelayFwd := instWinchM2.RelayFwd;
WinchM2FinalInterlockRequest.RequestedRelayRev := instWinchM2.RelayRev;
WinchM2FinalInterlockRequest.RequestedContactor1 := instWinchM2.Contactor1;
WinchM2FinalInterlockRequest.RequestedContactor2 := instWinchM2.Contactor2;
WinchM2FinalInterlockRequest.RequestedContactor3 := instWinchM2.Contactor3;
WinchM2FinalInterlockRequest.RequestedContactor4 := instWinchM2.Contactor4;
WinchM2FinalInterlockRequest.RequestedStep := instWinchM2.StepNumber;
WinchM2FinalInterlockRequest.PowerCutOff := instSafetyWinchM2.PowerCutOff;

{endregion}

{region "§8 Publication etats IHM"}
// === 📤 §8 PUBLICATION ÉTATS IHM (faits publics, lecture seule) ===
// : MeasuredSpeed_Mps jamais recopié, restait
// à 0.0 en permanence à l'IHM. SpeedDelta_Mps corrigé par rapport à la proposition initiale de
// l'agent (M1-M2, faux sens) -- le commentaire du type (ST_WinchState.st) dit explicitement
// "variation de vitesse ENTRE DEUX SCANS", pas un écart M1/M2 (qui existe déjà ailleurs via
// SyncStateHMI.DeltaPos_M/instWinchSync). Delta temporel via mémoire scan précédent.
WinchM1State.MeasuredSpeed_Mps := PRG_02_Acquisition.M1_Speed_Mps;
